const ESPECIES=[{"k":"Anser anser","common":"Ganso doméstico","alt":"Ganso blanco · Domestic Goose","sci":"Anser anser (doméstico)","family":"Anatidae","iucn":"LC","mig":false,"dom":true,"feral":false,"conf":"alta","desc":"Descendiente del ánsar común europeo, domesticado hace miles de años. Blanco, con pico y patas anaranjados. Muy vigilante: avisa a gritos de cualquier visita.","diet":"Pasto, hojas tiernas, semillas y granos.","habitat":"Prados y orillas de la laguna de la hacienda.","sw":["#F4F4F0","#E8875B"],"photos":[{"img":"../bogota/fotos/anser.jpg","mini":"../bogota/fotos/mini/anser.jpg","ind":"Descansando junto a la laguna","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Gregario y territorial; hace de guardián con sus graznidos.","donde":"Orillas de la laguna y prados, todo el año.","id":"anser-domesticus"}],"en":"Domestic Goose","enAlt":"Ganso doméstico · Ganso blanco","g":0},{"k":"Spatula discors","common":"Pato careto","alt":"Barraquete aliazul · Blue-winged Teal","sci":"Spatula discors","family":"Anatidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Pato pequeño. El macho tiene la cabeza gris azulada con una media luna blanca entre el ojo y el pico, el cuerpo pardo moteado y una mancha blanca a los lados de la cola. En vuelo muestra un parche azul celeste en el ala, que le da el nombre en inglés.","diet":"Semillas de plantas acuáticas, lenteja de agua, insectos acuáticos, caracoles y pequeños crustáceos que filtra en la superficie.","habitat":"Cría en las lagunas de las praderas de Canadá y EE. UU. Inverna en humedales, lagunas y arrozales desde México hasta el norte de Suramérica; en la Sabana, en humedales con vegetación flotante.","sw":["#7D8794","#F2F2EE","#7A5B3E","#7FB8DA"],"photos":[{"img":"../bogota/fotos/spatula.jpg","mini":"../bogota/fotos/mini/spatula.jpg","ind":"Macho, con la media luna blanca en la cara","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/spatula2.jpg","mini":"../bogota/fotos/mini/spatula2.jpg","ind":"Macho nadando entre lenteja de agua","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Se alimenta flotando y filtrando la superficie, a veces con la cabeza bajo el agua. Es tímido y despega en vuelo rápido y bajo ante cualquier movimiento. En invernada se junta en grupos con otros patos.","donde":"Espejos de agua del humedal cubiertos de lenteja de agua, sobre todo en la mañana. De septiembre a abril.","id":"spatula-discors"}],"en":"Blue-winged Teal","enAlt":"Pato careto · Barraquete aliazul","g":0},{"k":"Cairina moschata","common":"Pato criollo","alt":"Pato real doméstico · Muscovy Duck","sci":"Cairina moschata","family":"Anatidae","iucn":"LC","mig":false,"dom":true,"feral":true,"conf":"alta","desc":"Pato grande con carúnculas rojas en la cara. Los de la hacienda viven libres y crían por su cuenta, pero descienden de patos domésticos: lo delatan el plumaje gris, blanco o manchado y la cara muy roja. El pato silvestre es todo negro con brillo verde, tiene solo un parche blanco en el ala y vive en humedales de tierras bajas, no en la Sabana.","diet":"Plantas acuáticas, semillas, insectos, lombrices y pequeños animales del agua; también el alimento que se les da.","habitat":"Lagunas y prados de la hacienda. Es de las pocas aves domesticadas en América antes de la llegada de los europeos.","sw":["#1E1E22","#9C9893","#D23A2E"],"photos":[{"img":"../bogota/fotos/cairina.jpg","mini":"../bogota/fotos/mini/cairina.jpg","ind":"Patos libres con su nidada en la laguna","place":"Hacienda San Simón, Guaymaral"},{"img":"../boyaca/fotos/cairina.jpg","mini":"../boyaca/fotos/mini/cairina.jpg","ind":"Nadando en la laguna, con las carúnculas rojas","place":"Arcabuco, Boyacá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Tranquilos y poco ruidosos: el macho casi no tiene voz y sisea. Las hembras crían nidadas grandes y las cuidan en el agua.","donde":"Laguna y prados cercanos, todo el año.","id":"cairina-moschata"},{"l":"boyaca","nom":"Boyacá","hab":"Tranquilo y poco ruidoso; el macho sisea.","donde":"Laguna de la finca.","id":"cairina-moschata"}],"en":"Muscovy Duck","enAlt":"Pato criollo · Pato real doméstico","g":0},{"k":"Oxyura jamaicensis","common":"Pato turrio","alt":"Pato andino · Ruddy Duck","sci":"Oxyura jamaicensis","family":"Anatidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pato pequeño y compacto, de cola rígida que a menudo lleva levantada. El macho es castaño rojizo con la cabeza negra y un pico azul celeste brillante. La población de los Andes, más grande y de cabeza toda negra, a veces se considera una especie aparte, el pato andino (Oxyura ferruginea).","diet":"Semillas y raíces de plantas acuáticas, larvas de insectos y pequeños invertebrados que busca buceando.","habitat":"Lagunas y humedales con aguas abiertas y bordes de juncos y eneas, en tierras altas. En la Sabana depende de los pocos humedales que quedan.","sw":["#A8452A","#141414","#6EC2E8"],"photos":[{"img":"../bogota/fotos/oxyura.jpg","mini":"../bogota/fotos/mini/oxyura.jpg","ind":"Macho, con el pico azul celeste","place":"Humedal de Córdoba, Bogotá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Bucea con frecuencia y casi nunca sale del agua; prefiere nadar a volar. En celo, el macho infla el cuello y golpea el agua con el pico para hacer burbujas.","donde":"Aguas abiertas del humedal, lejos de la orilla; lleve binoculares.","id":"oxyura-jamaicensis"}],"en":"Ruddy Duck","enAlt":"Pato turrio · Pato andino","g":0},{"k":"Dendrocygna autumnalis","common":"Pisingo","alt":"Iguasa común · Black-bellied Whistling-Duck","sci":"Dendrocygna autumnalis","family":"Anatidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pato de cuello largo, castaño, con la cara gris, el vientre negro, el pico rojo coral y las patas rosadas. En vuelo muestra una franja blanca ancha en el ala. Su llamado es un silbido agudo, de ahí lo de «pato silbador». A diferencia de otros patos, se posa en árboles y anida en huecos de troncos.","diet":"Semillas, granos (sobre todo arroz) y plantas acuáticas; come mucho de noche.","habitat":"Ciénagas, arrozales, potreros inundables y lagunas de tierras bajas.","sw":["#8A4E33","#1C1A1A","#F08070","#F4F2EE"],"photos":[{"img":"../cartagena/fotos/dendro.jpg","mini":"../cartagena/fotos/mini/dendro.jpg","ind":"Pareja entre el pasto","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/dendro2.jpg","mini":"../cartagena/fotos/mini/dendro2.jpg","ind":"Dos en vuelo, con la franja blanca del ala","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en parejas o grupos que silban al volar. De día descansa en la orilla o en árboles; al atardecer sale a comer a arrozales y potreros inundados.","donde":"Potreros húmedos y orillas de la ciénaga, al amanecer y al atardecer.","id":"dendrocygna-autumnalis"}],"en":"Black-bellied Whistling-Duck","enAlt":"Pisingo · Iguasa común","g":0},{"k":"Ortalis columbiana","common":"Guacharaca colombiana","alt":"Guacharaca · Colombian Chachalaca","sci":"Ortalis columbiana","family":"Cracidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave grande, parecida a una gallina delgada de cola larga, parda con la cabeza y el cuello grises. Es endémica de Colombia: no vive en ningún otro país. De cerca se le ven escamas blancas en el pecho.","diet":"Frutos, hojas tiernas, flores y brotes; baja al suelo a comer frutos caídos.","habitat":"Bosque seco, rastrojos, cañadas arborizadas y fincas con árboles frutales, en los valles interandinos.","sw":["#6E5A44","#7C7F84","#3A3A38"],"photos":[{"img":"../barichara/fotos/ortalis.jpg","mini":"../barichara/fotos/mini/ortalis.jpg","ind":"Caminando por una rama entre barbas de viejo","place":"Barichara, Santander"},{"img":"../cafetera/fotos/ortalis.jpg","mini":"../cafetera/fotos/mini/ortalis.jpg","ind":"Pareja a contraluz en un árbol seco con barbas de viejo","place":"Zona Cafetera"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Vive en grupos familiares que se mueven por las ramas caminando y saltando más que volando. Es arisca: al sentirse observada se esconde en la espesura.","donde":"Cañadas arborizadas y árboles frutales en las afueras del pueblo, mejor al amanecer.","id":"ortalis-columbiana"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Vive en grupos familiares que se mueven por las ramas caminando y saltando más que volando; al atardecer se posan en árboles secos y altos.","donde":"Árboles altos y secos al amanecer y al atardecer, guaduales y comederos con banano.","id":"ortalis-columbiana"}],"en":"Colombian Chachalaca","enAlt":"Guacharaca colombiana · Guacharaca","g":1},{"k":"Zenaida auriculata","common":"Torcaza","alt":"Torcaza naguiblanca · Eared Dove","sci":"Zenaida auriculata","family":"Columbidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Paloma pardo rosada con manchas negras en las coberteras del ala y una línea oscura detrás del ojo, la «oreja» que le da el nombre en inglés.","diet":"Semillas y granos que busca caminando en el suelo.","habitat":"Campos abiertos, cultivos de cereales, jardines y ciudades. Muy abundante en la Sabana.","sw":["#B39C8E","#8F7A6E","#2A2522","#9DB3B8"],"photos":[{"img":"../bogota/fotos/zenaida.jpg","mini":"../bogota/fotos/mini/zenaida.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina por el suelo picoteando semillas, en parejas o bandadas. Al despegar hace un ruido seco con las alas.","donde":"Prados y bordes de setos, picoteando el suelo; también en cables. Todo el año.","id":"zenaida-auriculata"}],"en":"Eared Dove","enAlt":"Torcaza · Torcaza naguiblanca","g":2},{"k":"Columbina talpacoti","common":"Tortolita rojiza","alt":"Abuelita · Ruddy Ground Dove","sci":"Columbina talpacoti","family":"Columbidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Paloma pequeña con manchas negras en las alas. El macho es rojizo con la cabeza gris azulada; la hembra, como la de la foto, es parda grisácea con un tinte rosado.","diet":"Semillas pequeñas que recoge caminando en el suelo.","habitat":"Patios, potreros, caminos y pueblos. Muy común y confiada.","sw":["#B48A7A","#A9AFB5","#1E1A18"],"photos":[{"img":"../barichara/fotos/columbina.jpg","mini":"../barichara/fotos/mini/columbina.jpg","ind":"Hembra posada en una rama","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Camina por el suelo en parejas o grupos pequeños picoteando semillas; al espantarse sale volando con un aleteo rápido.","donde":"Patios, caminos de tierra y potreros.","id":"columbina-talpacoti"}],"en":"Ruddy Ground Dove","enAlt":"Tortolita rojiza · Abuelita","g":2},{"k":"Coccyzus americanus","common":"Cuclillo piquiamarillo","alt":"Cuco de pico amarillo · Yellow-billed Cuckoo","sci":"Coccyzus americanus","family":"Cuculidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Esbelto y de cola larga, pardo grisáceo por encima y blanco puro por debajo. La mandíbula inferior amarilla y curva lo identifica; por debajo, la cola muestra grandes manchas blancas y en vuelo se ve rojizo en las alas. A diferencia del cuco europeo, cría a sus propios polluelos. Es muy propenso a estrellarse contra las ventanas: confunde el reflejo de árboles y cielo con paso libre. En la casa de San Simón ha habido dos choques, y en uno de ellos se logró salvar al ave.","diet":"Orugas peludas que otras aves evitan, cigarras, saltamontes y otros insectos grandes; algunos frutos.","habitat":"Cría en bosques abiertos y riberas de EE. UU. y sur de Canadá. Inverna en bosques y matorrales de Suramérica, sobre todo al oriente de los Andes, hasta Argentina.","sw":["#8C8070","#F4F2EE","#E3B23C","#B5683F"],"photos":[{"img":"../bogota/fotos/coccyzus.jpg","mini":"../bogota/fotos/mini/coccyzus.jpg","ind":"Adulto entre el follaje","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Muy sigiloso: se mueve despacio entre el follaje y puede quedarse inmóvil largo rato. Cuando caza, se lanza de golpe sobre una oruga. Su canto es un «ka-ka-ka-kau-kau» gutural que se acelera.","donde":"Árboles frondosos y frutales, como el durazno, en octubre–noviembre y abril–mayo. Mira con calma dentro del follaje.","id":"coccyzus-americanus"}],"en":"Yellow-billed Cuckoo","enAlt":"Cuclillo piquiamarillo · Cuco de pico amarillo","g":3},{"k":"Piaya cayana","common":"Cuco ardilla","alt":"Squirrel Cuckoo","sci":"Piaya cayana","family":"Cuculidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Castaño rojizo con el vientre gris, anillo ocular amarillo verdoso y una cola larguísima con puntas blancas. Se mueve entre las ramas corriendo y saltando como una ardilla, de ahí su nombre.","diet":"Orugas peludas, cigarras, saltamontes y otros insectos grandes; a veces lagartijas.","habitat":"Bordes de bosque, cafetales con sombrío y jardines arbolados.","sw":["#A8562E","#9EA4A8","#F4F4F0"],"photos":[{"img":"../cafetera/fotos/piaya.jpg","mini":"../cafetera/fotos/mini/piaya.jpg","ind":"Adulto, con la cola larga de puntas blancas","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Corre por las ramas y planea de un árbol a otro; se mueve despacio y en silencio.","donde":"Copas medias de árboles y bordes de cafetales.","id":"piaya-cayana"}],"en":"Squirrel Cuckoo","enAlt":"Cuco ardilla","g":3},{"k":"Crotophaga ani","common":"Garrapatero piquiliso","alt":"Garrapatero · Smooth-billed Ani","sci":"Crotophaga ani","family":"Cuculidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Negro, con aspecto escamado y desaliñado, cola larga y un pico alto, liso y comprimido, con una joroba arriba. Vive en grupos que comparten un solo nido, donde varias hembras ponen sus huevos y todos ayudan a criar.","diet":"Saltamontes y otros insectos, a menudo los que espanta el ganado; algunos frutos.","habitat":"Potreros, rastrojos y matorrales de tierras bajas.","sw":["#141418","#2A3040"],"photos":[{"img":"../cartagena/fotos/crotophaga.jpg","mini":"../cartagena/fotos/mini/crotophaga.jpg","ind":"Adulto en la copa de un arbusto","place":"Arjona, Bolívar"},{"img":"../pijino/fotos/crotophaga.jpg","mini":"../pijino/fotos/mini/crotophaga.jpg","ind":"Pareja en una rama","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en grupos familiares que se mueven juntos de arbusto en arbusto con vuelos cortos y planeados. Al amanecer se asolean con las alas abiertas.","donde":"Matorrales y cercas junto a potreros con ganado.","id":"crotophaga-ani"},{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Anda en grupos familiares que se mueven juntos con vuelos cortos y planeados; al amanecer se asolean con las alas abiertas.","donde":"Matorrales y cercas junto a potreros.","id":"crotophaga-ani"}],"en":"Smooth-billed Ani","enAlt":"Garrapatero piquiliso · Garrapatero","g":3},{"k":"Systellura longirostris","common":"Guardacaminos andino","alt":"Chotacabras · Band-winged Nightjar","sci":"Systellura longirostris","family":"Caprimulgidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Plumaje críptico gris, pardo, negro y crema que lo vuelve invisible sobre tejas, piedras o el suelo. El macho tiene una banda blanca en las alas y esquinas blancas en la cola, que solo se ven en vuelo. De día descansa inmóvil con los ojos casi cerrados.","diet":"Polillas, escarabajos y otros insectos voladores que caza al atardecer y de noche, en vuelos bajos sobre potreros y alrededor de las luces.","habitat":"Potreros, páramos, zonas rocosas y áreas abiertas con casas, entre unos 1.500 y 4.000 m. Anida directamente en el suelo, sin construir nido.","sw":["#5E5A52","#A39C8C","#E9E3D3","#2B2925"],"photos":[{"img":"../bogota/fotos/chordeiles.jpg","mini":"../bogota/fotos/mini/chordeiles.jpg","ind":"Descansando de día sobre el caballete del techo","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Nocturno. De día descansa inmóvil sobre el suelo, tejas o piedras, confiado en su camuflaje. Al anochecer sale a cazar en vuelos bajos y el macho canta desde el suelo o un techo un silbido largo, agudo y descendente, «tsiiiiuu», que se repite durante la noche.","donde":"De día, sobre caballetes de techos y zonas despejadas del suelo; muévete despacio porque es fácil espantarlo. De noche, escúchalo cerca de las casas y potreros. Todo el año.","id":"systellura-longirostris"}],"en":"Band-winged Nightjar","enAlt":"Guardacaminos andino · Chotacabras","g":4},{"k":"Amazilia tzacatl","common":"Amazilia colirrufa","alt":"Colibrí colirrufo · Rufous-tailed Hummingbird","sci":"Amazilia tzacatl","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí mediano, verde brillante, con el pico rojo de punta negra y la cola castaño rojiza. Es el colibrí más común de las tierras templadas y cálidas de Colombia.","diet":"Néctar de flores de jardín, heliconias y bebederos; también pequeños insectos y arañas.","habitat":"Jardines, cafetales, bordes de bosque y potreros con árboles, desde el nivel del mar hasta unos 1.800 m.","sw":["#3E8A4A","#E0442E","#A8502E"],"photos":[{"img":"../cafetera/fotos/amazilia.jpg","mini":"../cafetera/fotos/mini/amazilia.jpg","ind":"De espaldas en una cuerda, con la cola rufa y el pico rojo","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Muy territorial y agresiva: defiende un parche de flores o un bebedero y persigue a otros colibríes con chillidos secos.","donde":"Flores de jardín, heliconias y bebederos.","id":"amazilia-tzacatl"}],"en":"Rufous-tailed Hummingbird","enAlt":"Amazilia colirrufa · Colibrí colirrufo","g":5},{"k":"Eriocnemis mosquera","common":"Calzadito pechidorado","alt":"Paramero dorado · Golden-breasted Puffleg","sci":"Eriocnemis mosquera","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Colibrí mediano de pico recto y fino, verde con el pecho dorado bronceado y la cola oscura. Como todos los calzaditos, tiene plumas blancas y esponjosas que le cubren las patas, como si llevara calzas.","diet":"Néctar de flores de arbustos de alta montaña y pequeños insectos.","habitat":"Bordes de bosque altoandino y subpáramo, entre unos 2.400 y 3.600 m.","sw":["#3E7A3A","#B8A03A","#F4F4F0"],"photos":[{"img":"../cafetera/fotos/eriocnemis.jpg","mini":"../cafetera/fotos/mini/eriocnemis.jpg","ind":"Posado en una varilla, con las calzas blancas visibles","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Se posa con frecuencia en ramas bajas expuestas entre una flor y otra y defiende los arbustos en flor de otros colibríes.","donde":"Arbustos floridos en bordes de bosque altoandino y jardines de montaña.","id":"eriocnemis-mosquera"}],"en":"Golden-breasted Puffleg","enAlt":"Calzadito pechidorado · Paramero dorado","g":5},{"k":"Colibri coruscans","common":"Colibrí chillón","alt":"Orejivioleta ventriazul · Sparkling Violetear","sci":"Colibri coruscans","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí grande, verde brillante, con un parche violeta azulado que va del ojo hacia la oreja y el pecho con reflejos azules. Lo distingue del orejivioleta verde el parche azul violeta en el centro del vientre, bien visible en las fotos de Monserrate. Su canto, un «chip» metálico repetido sin parar desde una percha, le da el nombre.","diet":"Néctar de flores tubulares como la antorcha (Kniphofia), las fucsias y los bebederos; insectos pequeños.","habitat":"Jardines, bordes de bosque, matorrales y páramo, desde unos 1.500 hasta 3.500 m. Muy adaptado a parques y casas de la Sabana.","sw":["#2EA44F","#4B5FD0","#2A6DB5"],"photos":[{"img":"../bogota/fotos/coruscansM1.jpg","mini":"../bogota/fotos/mini/coruscansM1.jpg","ind":"Macho, con el parche azul del vientre","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/coruscansM2.jpg","mini":"../bogota/fotos/mini/coruscansM2.jpg","ind":"De frente, con la oreja violeta","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/coruscansM3.jpg","mini":"../bogota/fotos/mini/coruscansM3.jpg","ind":"De perfil sobre una rama con musgo","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/coruscans.jpg","mini":"../bogota/fotos/mini/coruscans.jpg","ind":"Libando en una flor de antorcha (Kniphofia)","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Muy territorial: defiende flores y bebederos a gritos y en persecuciones aéreas. Canta largo rato desde una percha alta y expuesta.","donde":"Bebederos y flores de antorcha, fucsias y salvias. Todo el año.","id":"colibri-coruscans"}],"en":"Sparkling Violetear","enAlt":"Colibrí chillón · Orejivioleta ventriazul","g":5},{"k":"Lesbia victoriae","common":"Colibrí colilargo negro","alt":"Black-tailed Trainbearer","sci":"Lesbia victoriae","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí verde con una cola negra, delgada y larguísima: en el macho llega a medir más que el resto del cuerpo. La hembra, como la de la foto, tiene la cola algo más corta y el vientre ante con motas verdes.","diet":"Néctar de flores de arbustos y de bebederos; insectos pequeños.","habitat":"Matorrales, bordes de bosque altoandino, jardines y parques, entre unos 2.500 y 4.000 m. Es común en los cerros de Bogotá.","sw":["#3E8A4A","#141418","#D8C29A"],"photos":[{"img":"../bogota/fotos/lesbia.jpg","mini":"../bogota/fotos/mini/lesbia.jpg","ind":"Junto al bebedero, con la cola larguísima","place":"Cerro de Monserrate, Bogotá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Vuela con la cola larga ondeando como una cinta y hace un zumbido seco. Se posa a menudo en ramitas expuestas entre visita y visita a las flores.","donde":"Bebederos y matorrales floridos del sendero y la cima de Monserrate.","id":"lesbia-victoriae"}],"en":"Black-tailed Trainbearer","enAlt":"Colibrí colilargo negro","g":5},{"k":"Florisuga mellivora","common":"Colibrí nuquiblanco","alt":"Jacobino · White-necked Jacobin","sci":"Florisuga mellivora","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Colibrí grande y llamativo: el macho tiene la cabeza y el pecho azul intenso, una media luna blanca en la nuca, la espalda verde, el vientre blanco y la cola blanca con un borde negro.","diet":"Néctar de flores en la copa de los árboles e insectos que atrapa al vuelo.","habitat":"Bordes de bosque húmedo, cafetales con sombra y jardines con flores, hasta unos 1.600 m.","sw":["#2A3A9A","#F4F4F2","#3E8A4A"],"photos":[{"img":"../cafetera/fotos/florisuga.jpg","mini":"../cafetera/fotos/mini/florisuga.jpg","ind":"Macho en vuelo, abriendo la cola blanca","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Territorial en las flores; persigue a otros colibríes y caza insectos al vuelo en el aire abierto.","donde":"Árboles en flor y bebederos de colibríes.","id":"florisuga-mellivora"}],"en":"White-necked Jacobin","enAlt":"Colibrí nuquiblanco · Jacobino","g":5},{"k":"Aglaeactis cupripennis","common":"Colibrí rayo de sol","alt":"Rayito brillante · Shining Sunbeam","sci":"Aglaeactis cupripennis","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí canela rojizo, de pico corto y recto. Cuando gira, la espalda baja muestra un brillo morado, dorado y verde que le da el nombre.","diet":"Néctar de flores de arbustos de páramo y bebederos; insectos pequeños.","habitat":"Bordes de bosque altoandino, subpáramo y matorrales, entre unos 2.600 y 3.600 m.","sw":["#C2733A","#7A3A8A","#D8A84A"],"photos":[{"img":"../bogota/fotos/aglaeactis.jpg","mini":"../bogota/fotos/mini/aglaeactis.jpg","ind":"En vuelo frente al bebedero","place":"Cerro de Monserrate, Bogotá"},{"img":"../cafetera/fotos/aglaeactis.jpg","mini":"../cafetera/fotos/mini/aglaeactis.jpg","ind":"Posado sobre un arbusto de fucsias","place":"Zona Cafetera"},{"img":"../cafetera/fotos/aglaeactis2.jpg","mini":"../cafetera/fotos/mini/aglaeactis2.jpg","ind":"Revoloteando sobre las flores","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Territorial: defiende sus flores y bebederos desde una percha expuesta.","donde":"Bebederos y arbustos con flores en la cima de Monserrate.","id":"aglaeactis-cupripennis"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Territorial: defiende sus flores desde una percha expuesta en lo alto de un arbusto.","donde":"Arbustos con flores en zonas altas, como fucsias.","id":"aglaeactis-cupripennis"}],"en":"Shining Sunbeam","enAlt":"Colibrí rayo de sol · Rayito brillante","g":5},{"k":"Boissonneaua flavescens","common":"Coronita colianteada","alt":"Colibrí colihabano · Buff-tailed Coronet","sci":"Boissonneaua flavescens","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí robusto de pico corto y recto, verde brillante con el pecho moteado de verde sobre fondo claro, una mancha canela en el costado y la cola color ante con las puntas oscuras, que se ve muy bien cuando la abre.","diet":"Néctar de flores de árboles y arbustos del bosque andino, y de bebederos; también pequeños insectos.","habitat":"Bosque de niebla y bordes de bosque andino, entre unos 1.800 y 3.000 m.","sw":["#3E9A5A","#C89A5A","#B8703A"],"photos":[{"img":"../boyaca/fotos/boissonneaua.jpg","mini":"../boyaca/fotos/mini/boissonneaua.jpg","ind":"Adulto en una rama con musgo: pecho verde moteado y cola color ante","place":"Arcabuco, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"Al posarse levanta las alas sobre la espalda un instante, un gesto que lo delata. Es dominante en los bebederos y defiende las flores con persecuciones.","donde":"Ramas bajas con musgo en bordes de bosque y bebederos.","id":"boissonneaua-flavescens"}],"en":"Buff-tailed Coronet","enAlt":"Coronita colianteada · Colibrí colihabano","g":5},{"k":"Chaetocercus mulsant","common":"Estrellita ventriblanca","alt":"Rumbito · White-bellied Woodstar","sci":"Chaetocercus mulsant","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Colibrí diminuto, de unos 7,5 cm. El macho tiene gorguera magenta, pecho blanco y una mancha blanca en el flanco. La hembra es muy distinta: canela por debajo, con un antifaz oscuro y una ceja blanca detrás del ojo. Vuela recto y zumbando, más parecido a un abejorro que a otros colibríes.","diet":"Néctar de flores pequeñas y de bebederos; insectos diminutos como fuente de proteína.","habitat":"Bordes de bosque andino, jardines y matorrales floridos, entre unos 1.800 y 3.000 m.","sw":["#2E7D5B","#8E2A5E","#F2F2EE"],"photos":[{"img":"../bogota/fotos/chaetoM.jpg","mini":"../bogota/fotos/mini/chaetoM.jpg","ind":"Macho en vuelo, con la gorguera magenta","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/chaeto2.jpg","mini":"../bogota/fotos/mini/chaeto2.jpg","ind":"Macho en el bebedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/chaeto1.jpg","mini":"../bogota/fotos/mini/chaeto1.jpg","ind":"Macho en vuelo","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/chaetoF1.jpg","mini":"../bogota/fotos/mini/chaetoF1.jpg","ind":"Hembra: canela por debajo, con antifaz oscuro","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/chaetoF2.jpg","mini":"../bogota/fotos/mini/chaetoF2.jpg","ind":"Hembra en vuelo","place":"Cerro de Monserrate, Bogotá"},{"img":"../bogota/fotos/chaetoF3.jpg","mini":"../bogota/fotos/mini/chaetoF3.jpg","ind":"Hembra libando en el bebedero","place":"Cerro de Monserrate, Bogotá"},{"img":"../boyaca/fotos/chaetoF.jpg","mini":"../boyaca/fotos/mini/chaetoF.jpg","ind":"Hembra en vuelo","place":"Arcabuco, Boyacá"},{"img":"../boyaca/fotos/chaetoF2.jpg","mini":"../boyaca/fotos/mini/chaetoF2.jpg","ind":"Hembra de perfil, con la cola de punta canela","place":"Arcabuco, Boyacá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Su vuelo zumbante y recto recuerda a un abejorro. Se posa en ramitas finas y expuestas, y cede el paso a los colibríes más grandes que la persiguen.","donde":"Bebederos y arbustos con flores pequeñas como salvias y lantanas. Temprano en la mañana y al final de la tarde. Todo el año.","id":"chaetocercus-mulsant"},{"l":"boyaca","nom":"Boyacá","hab":"Vuela zumbando como un abejorro y se posa en ramitas finas; cede el paso a colibríes más grandes.","donde":"Bebederos y arbustos floridos.","id":"chaetocercus-mulsant"}],"en":"White-bellied Woodstar","enAlt":"Estrellita ventriblanca · Rumbito","g":5},{"k":"Colibri cyanotus","common":"Orejivioleta verde","alt":"Chillón menor · Lesser Violetear","sci":"Colibri cyanotus","family":"Trochilidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Colibrí verde brillante con una mancha violeta que va del ojo a la oreja y una banda oscura en la cola. Más pequeño que su pariente el colibrí chillón, y sin azul en el pecho ni en el vientre.","diet":"Néctar de flores de arbustos y árboles del bosque; insectos pequeños.","habitat":"Bordes y claros de bosque de montaña, entre unos 1.200 y 3.000 m.","sw":["#2EA44F","#6A4FD0","#1E2A2A"],"photos":[{"img":"../boyaca/fotos/cyanotus.jpg","mini":"../boyaca/fotos/mini/cyanotus.jpg","ind":"Adulto, con la mancha violeta en la oreja","place":"Arcabuco, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"Canta un «chip» metálico repetido desde perchas altas; defiende las flores de otros colibríes.","donde":"Ramas expuestas en bordes de bosque y arbustos en flor.","id":"colibri-cyanotus"}],"en":"Lesser Violetear","enAlt":"Orejivioleta verde · Chillón menor","g":5},{"k":"Aramus guarauna","common":"Carrao","alt":"Correa · Limpkin","sci":"Aramus guarauna","family":"Aramidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave grande, parda oscura con el cuello salpicado de manchas blancas y un pico largo, algo curvo y torcido en la punta. Es la única especie de su familia en el mundo. Su grito nocturno, un lamento fuerte y largo, ha dado lugar a leyendas en muchos pueblos ribereños.","diet":"Casi solo caracoles grandes de agua dulce; la punta torcida del pico le sirve para sacarlos de la concha sin romperla.","habitat":"Ciénagas, pantanos y orillas con vegetación densa.","sw":["#5A3E2A","#F4F0E8","#B89A5A"],"photos":[{"img":"../pijino/fotos/aramus.jpg","mini":"../pijino/fotos/mini/aramus.jpg","ind":"Adulto entre las ramas de la orilla","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Camina despacio entre la vegetación, con un paso que parece cojo. Grita sobre todo al amanecer, al atardecer y de noche.","donde":"Orillas con arbustos y vegetación densa; donde hay montones de conchas de caracol vacías.","id":"aramus-guarauna"}],"en":"Limpkin","enAlt":"Carrao · Correa","g":6},{"k":"Porphyrio martinica","common":"Tingua azul","alt":"Calamón morado · Purple Gallinule","sci":"Porphyrio martinica","family":"Rallidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"De las aves más coloridas de la Sabana: cabeza y pecho azul violeta, espalda verde turquesa, pico rojo con punta amarilla, un escudo celeste en la frente y patas amarillas larguísimas.","diet":"Omnívora: semillas, hojas y flores de plantas acuáticas, insectos, caracoles, ranas pequeñas y hasta huevos de otras aves.","habitat":"Humedales con juncos, eneas y vegetación flotante. Sus dedos muy largos le reparten el peso para caminar sobre las plantas que flotan.","sw":["#3A2FA0","#1F9A8A","#E2321F","#F2C21A","#A9D8EC"],"photos":[{"img":"../bogota/fotos/porphyrio.jpg","mini":"../bogota/fotos/mini/porphyrio.jpg","ind":"Caminando entre los juncos","place":"Humedal de Córdoba, Bogotá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina despacio sobre la vegetación flotante, sacudiendo la cola corta y mostrando el blanco de debajo. Trepa por los juncos con habilidad y es algo tímida.","donde":"Orillas de la laguna con juncos y plantas flotantes, temprano en la mañana. Todo el año.","id":"porphyrio-martinica"}],"en":"Purple Gallinule","enAlt":"Tingua azul · Calamón morado","g":6},{"k":"Fulica americana","common":"Tingua de pico amarillo","alt":"Focha americana · American Coot","sci":"Fulica americana","family":"Rallidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave acuática gris pizarra con la cabeza negra y un pico y escudo frontal amarillos. Nada como un pato, pero no lo es: es pariente de las tinguas y tiene los dedos lobulados en vez de palmeados.","diet":"Plantas acuáticas que arranca buceando o picoteando en la superficie; también insectos, caracoles y pequeños invertebrados.","habitat":"Lagunas y humedales con aguas abiertas y bordes de juncos. La población de los Andes de Colombia es residente y se considera una subespecie propia.","sw":["#4E555C","#111214","#E8C83A"],"photos":[{"img":"../bogota/fotos/fulica.jpg","mini":"../bogota/fotos/mini/fulica.jpg","ind":"Posada sobre una rama en el agua; otra nada al fondo","place":"Humedal de Córdoba, Bogotá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Gregaria y ruidosa. Bucea para arrancar plantas, mueve la cabeza adelante y atrás al nadar y defiende su espacio corriendo sobre el agua con salpicaduras. Para despegar necesita carrera.","donde":"Aguas abiertas de la laguna y troncos donde se posa a descansar. Todo el año.","id":"fulica-americana"}],"en":"American Coot","enAlt":"Tingua de pico amarillo · Focha americana","g":6},{"k":"Gallinula galeata","common":"Tingua de pico rojo","alt":"Polla de agua · Gallareta común · Common Gallinule","sci":"Gallinula galeata","family":"Rallidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Del tamaño de una gallina pequeña, gris pizarra casi negra, con un escudo rojo en la frente y el pico rojo de punta amarilla. Tiene una línea blanca a lo largo del flanco y la parte inferior de la cola blanca, que mueve al caminar. Los juveniles son pardos y grises, sin rojo en el pico.","diet":"Brotes, semillas y hojas de plantas acuáticas, caracoles, insectos y lombrices.","habitat":"Humedales, lagunas y canales con orillas de vegetación densa, desde el nivel del mar hasta la Sabana.","sw":["#2A2E34","#D8322A","#E8D23A","#F4F4F0"],"photos":[{"img":"../bogota/fotos/gallinula.jpg","mini":"../bogota/fotos/mini/gallinula.jpg","ind":"Adulto caminando entre la vegetación del humedal, con la línea blanca del flanco","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/gallinula2.jpg","mini":"../bogota/fotos/mini/gallinula2.jpg","ind":"Adulto con un juvenil, pardo y sin escudo rojo","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina sobre las plantas flotantes moviendo la cabeza y la cola a cada paso, y nada como un pato. Es tímida: al menor susto corre a esconderse entre los juncos.","donde":"Orillas con vegetación densa del humedal de la hacienda, en las mañanas tranquilas.","id":"gallinula-galeata"}],"en":"Common Gallinule","enAlt":"Tingua de pico rojo · Polla de agua · Gallareta común","g":6},{"k":"Vanellus chilensis","common":"Alcaraván","alt":"Pellar común · Southern Lapwing","sci":"Vanellus chilensis","family":"Charadriidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Gris pardo con hombros de brillo bronce y verde, pecho negro, copete fino y ojo rojo. Tiene un espolón en el ala que usa para defender el nido.","diet":"Lombrices, insectos y larvas que saca del suelo en potreros y prados.","habitat":"Pastizales, potreros, canchas y orillas de humedales. Anida en el suelo y defiende a gritos y en vuelos rasantes a cualquiera que se acerque.","sw":["#8C8A78","#1F2A44","#F4F4F0","#B53A44"],"photos":[{"img":"../bogota/fotos/vanellus.jpg","mini":"../bogota/fotos/mini/vanellus.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/vanellus2.jpg","mini":"../bogota/fotos/mini/vanellus2.jpg","ind":"Caminando en el prado","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Vigilante y ruidoso: anda en parejas y da la alarma a gritos ante cualquier intruso. En época de cría se lanza en vuelos rasantes contra personas, perros o rapaces que se acerquen al nido.","donde":"Potreros abiertos y prados recién cortados. Si grita y vuela sobre ti, hay un nido cerca: aléjate despacio. Todo el año.","id":"vanellus-chilensis"}],"en":"Southern Lapwing","enAlt":"Alcaraván · Pellar común","g":7},{"k":"Jacana jacana","common":"Gallito de ciénaga","alt":"Jacana carunculada · Wattled Jacana","sci":"Jacana jacana","family":"Jacanidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Negro y castaño, con un escudo rojo en la frente, carúnculas rojas a los lados del pico y pico amarillo. Sus dedos larguísimos le reparten el peso para caminar sobre las hojas que flotan. En vuelo muestra las plumas de las alas amarillo verdosas. Los papeles están invertidos: la hembra defiende el territorio y tiene varias parejas, y son los machos los que incuban y cuidan a los pichones.","diet":"Insectos, caracoles, pececitos y semillas que recoge de la vegetación flotante.","habitat":"Ciénagas, lagunas y canales con buchón, lirios y otras plantas flotantes.","sw":["#2A1A16","#D22A2A","#E8C83A","#C8D06A"],"photos":[{"img":"../cartagena/fotos/jacana.jpg","mini":"../cartagena/fotos/mini/jacana.jpg","ind":"Adulto caminando sobre hojas flotantes","place":"Arjona, Bolívar"},{"img":"../pijino/fotos/jacana.jpg","mini":"../pijino/fotos/mini/jacana.jpg","ind":"Adulto caminando en el pasto húmedo","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/jacanaJuv.jpg","mini":"../pijino/fotos/mini/jacanaJuv.jpg","ind":"Juvenil: blanco por debajo, con ceja clara","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Camina despacio sobre la vegetación flotante. Al aterrizar levanta las alas y muestra el amarillo. Es ruidoso y defiende su espacio a gritos.","donde":"Espejos de agua con lirios y buchón, a cualquier hora.","id":"jacana-jacana"},{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Camina sobre la vegetación flotante. Al aterrizar levanta las alas y muestra el amarillo. Es ruidoso y defiende su espacio a gritos.","donde":"Espejos de agua con plantas flotantes y potreros encharcados.","id":"jacana-jacana"}],"en":"Wattled Jacana","enAlt":"Gallito de ciénaga · Jacana carunculada","g":7},{"k":"Leucophaeus atricilla","common":"Gaviota reidora","alt":"Gaviota guanaguanare · Laughing Gull","sci":"Leucophaeus atricilla","family":"Laridae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Gaviota mediana de manto gris oscuro, puntas de las alas negras, patas y pico oscuros. En la época de cría la cabeza se vuelve negra; el resto del año, como en la foto, la cabeza es blanca con un manchón gris detrás del ojo. Su nombre viene de la llamada, que parece una carcajada.","diet":"Peces pequeños, camarones, cangrejos, insectos y restos que dejan los barcos y los pescadores.","habitat":"Bahías, puertos, playas y desembocaduras de la costa Caribe.","sw":["#5E646C","#F4F4F2","#141414"],"photos":[{"img":"../cartagena/fotos/leucophaeus.jpg","mini":"../cartagena/fotos/mini/leucophaeus.jpg","ind":"Adulto en plumaje de invierno, a punto de posarse en el agua","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/leucophaeus2.jpg","mini":"../cartagena/fotos/mini/leucophaeus2.jpg","ind":"Joven de primer invierno sobre la bahía: alas pardas y banda negra en la cola","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en grupos que siguen a las lanchas y a los pescadores, se posan en boyas y muelles y bajan en picada corta a recoger comida de la superficie.","donde":"Muelles, boyas y el borde de la bahía frente al paseo, sobre todo de octubre a abril.","id":"leucophaeus-atricilla"}],"en":"Laughing Gull","enAlt":"Gaviota reidora · Gaviota guanaguanare","g":7},{"k":"Thalasseus maximus","common":"Gaviotín real","alt":"Charrán real · Royal Tern","sci":"Thalasseus maximus","family":"Laridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Ave marina blanca y gris perla, con una cresta negra despeinada en la nuca y pico grueso anaranjado. Muchos de los que se ven en el Caribe colombiano llegan desde las costas de Norteamérica fuera de su época de cría.","diet":"Peces pequeños que atrapa lanzándose en picada al agua.","habitat":"Costas, playas, bahías y desembocaduras; descansa en grupos sobre troncos, bancos de arena y muelles.","sw":["#F7F7F5","#C8CED4","#F08A3A","#151515"],"photos":[{"img":"../cartagena/fotos/thalasseusMG.jpg","mini":"../cartagena/fotos/mini/thalasseusMG.jpg","ind":"Adulto en plumaje de invierno sobre la bahía: frente blanca, cola ahorquillada","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/thalasseusIR.jpg","mini":"../cartagena/fotos/mini/thalasseusIR.jpg","ind":"En vuelo, con el pico anaranjado y la cresta negra","place":"Islas del Rosario y Barú"},{"img":"../cartagena/fotos/thalasseus.jpg","mini":"../cartagena/fotos/mini/thalasseus.jpg","ind":"Grupo descansando sobre un tronco, junto a patos cuervo","place":"Canal del Dique, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Descansa en grupos ruidosos, todos mirando contra el viento. Pesca volando sobre el agua con el pico hacia abajo y se lanza en picada.","donde":"Troncos, bancos de arena y muelles cerca del mar y de la boca del canal.","id":"thalasseus-maximus"}],"en":"Royal Tern","enAlt":"Gaviotín real · Charrán real","g":7},{"k":"Gallinago nobilis","common":"Caica","alt":"Becasina paramuna · Noble Snipe","sci":"Gallinago nobilis","family":"Scolopacidae","iucn":"NT","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Ave limícola rechoncha, de patrón críptico pardo, negro y ante, con un pico recto y larguísimo. Suele quedarse inmóvil y salir volando en zigzag solo cuando se le pisa casi encima.","diet":"Lombrices, larvas e invertebrados que detecta hundiendo el pico en el barro.","habitat":"Humedales, turberas, potreros encharcados y bordes de páramo, entre unos 2.000 y 4.000 m. Depende de que los humedales de la Sabana se conserven.","sw":["#6B5233","#C8AE84","#2E2418"],"photos":[{"img":"../bogota/fotos/gallinago.jpg","mini":"../bogota/fotos/mini/gallinago.jpg","ind":"Adulto en aguas someras","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Solitaria y difícil de ver. Confía en su camuflaje y se queda inmóvil; si se le acerca alguien, sale volando en zigzag con un grito ronco. Come hundiendo el pico en el barro una y otra vez.","donde":"Bordes del humedal y zonas de lodo con vegetación baja. Muévete despacio y temprano en la mañana. Todo el año.","id":"gallinago-nobilis"}],"en":"Noble Snipe","enAlt":"Caica · Becasina paramuna","g":7},{"k":"Fregata magnificens","common":"Fragata","alt":"Tijereta de mar · Magnificent Frigatebird","sci":"Fregata magnificens","family":"Fregatidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Los juveniles tienen la cabeza y el pecho blancos. Ave marina negra, de alas larguísimas y angulosas (más de 2 m de envergadura) y cola profundamente ahorquillada en forma de tijera. El macho infla en época de cría una enorme bolsa roja en la garganta; la hembra, como la de la primera foto, tiene el pecho blanco. Pesa muy poco para su tamaño: puede pasar días en el aire sin posarse.","diet":"Peces voladores y otros peces que atrapa de la superficie sin mojarse, y comida que roba en vuelo a pelícanos, gaviotines y piqueros, persiguiéndolos hasta que la sueltan. No puede posarse en el agua: sus plumas no son impermeables.","habitat":"Costas, islas y mar abierto del Caribe y el Pacífico; anida en colonias sobre manglares y arbustos de islas.","sw":["#141418","#F4F4F0","#D2282A"],"photos":[{"img":"../cartagena/fotos/fregata.jpg","mini":"../cartagena/fotos/mini/fregata.jpg","ind":"Hembra, con el pecho blanco","place":"Islas del Rosario y Barú"},{"img":"../cartagena/fotos/fregata2.jpg","mini":"../cartagena/fotos/mini/fregata2.jpg","ind":"Silueta con la cola en tijera","place":"Islas del Rosario y Barú"},{"img":"../cartagena/fotos/fregataJuv.jpg","mini":"../cartagena/fotos/mini/fregataJuv.jpg","ind":"Juvenil, con la cabeza y el pecho blancos, sobre la bahía","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Planea durante horas casi sin mover las alas, aprovechando el viento sobre las islas. Abre y cierra la cola en tijera para maniobrar.","donde":"Cielo sobre las islas y las playas de Barú; mire hacia arriba, sobre todo donde hay pescadores.","id":"fregata-magnificens"}],"en":"Magnificent Frigatebird","enAlt":"Fragata · Tijereta de mar","g":8},{"k":"Nannopterum brasilianum","common":"Pato cuervo","alt":"Cormorán neotropical · Neotropic Cormorant","sci":"Nannopterum brasilianum","family":"Phalacrocoracidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Negro, de cuello largo, cola larga y pico ganchudo con piel amarilla en la base. Sus plumas no son del todo impermeables: eso le ayuda a hundirse al bucear, pero después tiene que posarse con las alas abiertas para secarlas al sol.","diet":"Peces que persigue buceando, impulsándose con las patas palmeadas.","habitat":"Ciénagas, ríos, lagunas, manglares y costas.","sw":["#141416","#E8B83A"],"photos":[{"img":"../cartagena/fotos/nannopterum.jpg","mini":"../cartagena/fotos/mini/nannopterum.jpg","ind":"Tres posados en ramas secas sobre el agua","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/nannopterum2.jpg","mini":"../cartagena/fotos/mini/nannopterum2.jpg","ind":"En vuelo","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/nannopterum3.jpg","mini":"../cartagena/fotos/mini/nannopterum3.jpg","ind":"Grupo en la copa de un árbol: uno seca las alas abiertas al sol y otro despega","place":"Canal del Dique, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Bucea durante muchos segundos y reaparece lejos. Pasa largos ratos posado en ramas secas sobre el agua, a menudo con las alas abiertas para secarlas.","donde":"Ramas y troncos secos dentro del agua, a lo largo del canal.","id":"nannopterum-brasilianum"}],"en":"Neotropic Cormorant","enAlt":"Pato cuervo · Cormorán neotropical","g":8},{"k":"Bubulcus ibis","common":"Garcita del ganado","alt":"Garcilla bueyera · Cattle Egret","sci":"Bubulcus ibis","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Garza blanca pequeña y rechoncha, con pico corto amarillo anaranjado. En época de cría le salen plumas color canela en la cabeza, el pecho y la espalda. Es originaria de África: a finales del siglo XIX cruzó el Atlántico por sus propios medios, llegó a Suramérica y en pocas décadas se extendió por todo el continente siguiendo a la ganadería.","diet":"Saltamontes, lombrices y otros insectos que espanta el ganado o la podadora; también ranas y lagartijas.","habitat":"Potreros con ganado, prados, campos arados y orillas de humedales, desde el nivel del mar hasta la Sabana.","sw":["#F7F7F5","#E8A86A","#F08A3A"],"photos":[{"img":"../bogota/fotos/bubulcusSS.jpg","mini":"../bogota/fotos/mini/bubulcusSS.jpg","ind":"En plumaje de cría, con plumas canela en la cabeza y la espalda, atrapando un insecto en el prado","place":"Hacienda San Simón, Guaymaral"},{"img":"../cartagena/fotos/bubulcus.jpg","mini":"../cartagena/fotos/mini/bubulcus.jpg","ind":"Caminando en el potrero","place":"Arjona, Bolívar"},{"img":"../boyaca/fotos/bubulcus2.jpg","mini":"../boyaca/fotos/mini/bubulcus2.jpg","ind":"En plumaje de cría, llamando junto a los nidos","place":"Arcabuco, Boyacá"},{"img":"../boyaca/fotos/bubulcus4.jpg","mini":"../boyaca/fotos/mini/bubulcus4.jpg","ind":"Con la corona y el pecho color ante de la época de cría","place":"Arcabuco, Boyacá"},{"img":"../boyaca/fotos/bubulcus3.jpg","mini":"../boyaca/fotos/mini/bubulcus3.jpg","ind":"Adulto posado, con el pico anaranjado","place":"Arcabuco, Boyacá"},{"img":"../boyaca/fotos/bubulcus5.jpg","mini":"../boyaca/fotos/mini/bubulcus5.jpg","ind":"Colonia de nidos en los eucaliptos","place":"Arcabuco, Boyacá"},{"img":"../boyaca/fotos/bubulcus.jpg","mini":"../boyaca/fotos/mini/bubulcus.jpg","ind":"Abriendo las alas junto a un nido","place":"Arcabuco, Boyacá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina por el prado con pasos lentos y estira el cuello de golpe para atrapar insectos. Sigue al ganado y a las podadoras para comer lo que espantan.","donde":"Prados y potreros de la hacienda, sobre todo detrás del ganado.","id":"bubulcus-ibis"},{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Camina junto a las vacas y atrapa los insectos que estas espantan. Al atardecer vuela en bandadas a dormir en árboles junto al agua.","donde":"Potreros con ganado, todo el día.","id":"bubulcus-ibis"},{"l":"boyaca","nom":"Boyacá","hab":"Anida en colonias ruidosas: los adultos llaman con el pico abierto, abren las alas y se disputan las ramas junto a los nidos. De día sale a los potreros a caminar junto a las vacas.","donde":"Colonia de nidos en los eucaliptos y potreros con ganado de Arcabuco.","id":"bubulcus-ibis"}],"en":"Cattle Egret","enAlt":"Garcita del ganado · Garcilla bueyera","g":9},{"k":"Butorides striata","common":"Garcita rayada","alt":"Garcita estriada · Striated Heron","sci":"Butorides striata","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Garza pequeña y rechoncha, de patas amarillas cortas, corona negra y plumaje gris rayado. Camina agachada y se queda inmóvil antes de lanzar el picotazo.","diet":"Peces pequeños, ranas, cangrejos e insectos. Se ha visto usar «carnadas» —insectos o migas— para atraer peces.","habitat":"Orillas de ríos, quebradas, lagunas y embalses con piedras o vegetación.","sw":["#5A6070","#151515","#E8C83A"],"photos":[{"img":"../boyaca/fotos/butorides.jpg","mini":"../boyaca/fotos/mini/butorides.jpg","ind":"Acechando en la orilla","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/butorides2.jpg","mini":"../boyaca/fotos/mini/butorides2.jpg","ind":"Caminando agachada entre piedras","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"Solitaria y paciente: acecha agachada al borde del agua.","donde":"Orillas de quebradas y embalses del valle.","id":"butorides-striata"}],"en":"Striated Heron","enAlt":"Garcita rayada · Garcita estriada","g":9},{"k":"Egretta thula","common":"Garza patiamarilla","alt":"Garceta nívea · Snowy Egret","sci":"Egretta thula","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Garza blanca mediana con pico negro, piel amarilla entre el pico y el ojo y patas negras con «zapatos» amarillos. Hacia 1900 casi se extingue: sus plumas de cría se usaban en sombreros de moda. La indignación por esa cacería dio origen a las primeras leyes de protección de aves.","diet":"Peces pequeños, camarones e insectos. Agita el agua con las patas amarillas para espantar a sus presas.","habitat":"Ciénagas, lagunas, manglares y orillas de caños.","sw":["#F7F7F5","#151515","#E8C83A"],"photos":[{"img":"../cartagena/fotos/thula.jpg","mini":"../cartagena/fotos/mini/thula.jpg","ind":"Pescando en aguas someras","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Muy activa: corre, gira y agita el agua con las patas para sacar presas. Pesca en grupo con otras garzas.","donde":"Aguas someras y lodazales de la ciénaga.","id":"egretta-thula"}],"en":"Snowy Egret","enAlt":"Garza patiamarilla · Garceta nívea","g":9},{"k":"Ardea alba","common":"Garza real","alt":"Garceta grande · Great Egret","sci":"Ardea alba","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Garza blanca grande, de pico amarillo y patas negras, mucho más grande que la garza patiamarilla y la garcita del ganado. En época de cría le crecen plumas largas y finas en la espalda; por ellas casi desaparece hacia 1900, cuando se usaban en los sombreros de moda.","diet":"Peces, ranas, cangrejos e insectos grandes; caza caminando despacio o esperando inmóvil.","habitat":"Ciénagas, ríos, manglares, arrozales y potreros inundados.","sw":["#F7F7F5","#E8C03A","#151515"],"photos":[{"img":"../cartagena/fotos/alba2.jpg","mini":"../cartagena/fotos/mini/alba2.jpg","ind":"En vuelo, con las patas negras extendidas","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/alba.jpg","mini":"../cartagena/fotos/mini/alba.jpg","ind":"En la orilla, junto a un maizal","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/alba3.jpg","mini":"../cartagena/fotos/mini/alba3.jpg","ind":"Volando bajo sobre el canal","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/albaCD.jpg","mini":"../cartagena/fotos/mini/albaCD.jpg","ind":"Al acecho en la orilla, contra un muro de eneas","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/albaMG.jpg","mini":"../cartagena/fotos/mini/albaMG.jpg","ind":"En vuelo sobre la bahía, con el cuello recogido y las patas negras estiradas","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../pijino/fotos/alba2.jpg","mini":"../pijino/fotos/mini/alba2.jpg","ind":"Asomada sobre la vegetación de la orilla, con el pico amarillo","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/alba.jpg","mini":"../pijino/fotos/mini/alba.jpg","ind":"En vuelo al atardecer","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Camina despacio con el cuello estirado y se queda quieta acechando. Al atardecer vuela en grupos a dormir en árboles junto al agua.","donde":"Orillas del canal, potreros inundados y ciénagas.","id":"ardea-alba"},{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Camina despacio con el cuello estirado y se queda quieta acechando. Al atardecer vuela en grupos a dormir en árboles junto al agua.","donde":"Orillas de la ciénaga y potreros inundados.","id":"ardea-alba"}],"en":"Great Egret","enAlt":"Garza real · Garceta grande","g":9},{"k":"Ardea cocoi","common":"Garzón azul","alt":"Garza cuca · Cocoi Heron","sci":"Ardea cocoi","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"La garza más grande de Suramérica, de casi 1,3 m de alto. Cuello blanco, corona negra, dorso gris azulado, pico amarillo y largo. En vuelo recoge el cuello en forma de S y bate las alas despacio.","diet":"Peces grandes, que atrapa de un picotazo rápido después de esperar inmóvil; también cangrejos, ranas y culebras de agua.","habitat":"Ríos anchos, canales, ciénagas y manglares de tierras bajas.","sw":["#8E9AA8","#F4F4F0","#151515","#E8C83A"],"photos":[{"img":"../cartagena/fotos/cocoi.jpg","mini":"../cartagena/fotos/mini/cocoi.jpg","ind":"Adulto pescando en la orilla","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoi2.jpg","mini":"../cartagena/fotos/mini/cocoi2.jpg","ind":"Entre los mangles, con el pico abierto","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoi3.jpg","mini":"../cartagena/fotos/mini/cocoi3.jpg","ind":"En vuelo sobre el canal","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoi4.jpg","mini":"../cartagena/fotos/mini/cocoi4.jpg","ind":"Vigilando desde lo alto de un arbusto","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoi5.jpg","mini":"../cartagena/fotos/mini/cocoi5.jpg","ind":"Vuelo rasante sobre el agua","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoiVuelo.jpg","mini":"../cartagena/fotos/mini/cocoiVuelo.jpg","ind":"En vuelo alto, con el cuello recogido y las alas blancas y negras","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/cocoi6.jpg","mini":"../cartagena/fotos/mini/cocoi6.jpg","ind":"De pie en el agua, al acecho","place":"Canal del Dique, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Solitaria y paciente: puede pasar mucho tiempo inmóvil en la orilla antes de lanzar el picotazo. Al espantarse da un graznido ronco y se va volando bajo sobre el agua.","donde":"Orillas del canal y de las ciénagas, y árboles altos de la ribera.","id":"ardea-cocoi"}],"en":"Cocoi Heron","enAlt":"Garzón azul · Garza cuca","g":9},{"k":"Nycticorax nycticorax","common":"Guaco","alt":"Martinete común · Black-crowned Night-Heron","sci":"Nycticorax nycticorax","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Garza rechoncha, de cuello corto, con la corona y la espalda negras, el resto gris pálido y unos grandes ojos rojos adaptados para cazar de noche.","diet":"Peces, ranas, cangrejos e insectos que caza sobre todo al anochecer y de noche.","habitat":"Ciénagas, manglares y orillas con árboles, donde descansa de día en grupos.","sw":["#1E2A36","#B8BCC0","#C8282A"],"photos":[{"img":"../pijino/fotos/nycticorax.jpg","mini":"../pijino/fotos/mini/nycticorax.jpg","ind":"Adulto, de ojo rojo","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/nycticorax2.jpg","mini":"../pijino/fotos/mini/nycticorax2.jpg","ind":"Posado en ramas secas al atardecer","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"De día descansa encorvado en grupos, en árboles sobre el agua. Al anochecer sale a cazar y se oye un «cuac» seco en vuelo.","donde":"Árboles y ramas secas de la orilla, al atardecer.","id":"nycticorax-nycticorax"}],"en":"Black-crowned Night Heron","enAlt":"Guaco · Martinete común","g":9},{"k":"Tigrisoma lineatum","common":"Vaco colorado","alt":"Garza tigre · Rufescent Tiger-Heron","sci":"Tigrisoma lineatum","family":"Ardeidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"El juvenil, como el de la foto, es canela con barras negras, un camuflaje perfecto entre juncos y hojas secas. El adulto tiene la cabeza y el cuello castaño rojizo. Ante el peligro se queda inmóvil con el pico apuntando al cielo para confundirse con la vegetación.","diet":"Peces, ranas, cangrejos e insectos acuáticos que acecha inmóvil en la orilla.","habitat":"Orillas sombreadas de ciénagas, caños y bosques inundables.","sw":["#C8955A","#1E1A16","#8A3E26"],"photos":[{"img":"../pijino/fotos/tigrisoma.jpg","mini":"../pijino/fotos/mini/tigrisoma.jpg","ind":"Juvenil, con el barrado de «tigre»","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Solitario y paciente: se queda quieto largo rato en la orilla. Si se siente observado, estira el cuello hacia arriba y se balancea con los juncos.","donde":"Orillas sombreadas y bordes de caños, al amanecer.","id":"tigrisoma-lineatum"}],"en":"Rufescent Tiger-Heron","enAlt":"Vaco colorado · Garza tigre","g":9},{"k":"Pelecanus occidentalis","common":"Pelícano pardo","alt":"Alcatraz · Brown Pelican","sci":"Pelecanus occidentalis","family":"Pelecanidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave marina enorme, gris y parda, con la cabeza blanca amarillenta y una bolsa bajo el pico que se estira para atrapar peces. Es el único pelícano que pesca lanzándose en picada desde el aire.","diet":"Peces, sobre todo sardinas y lisas, que atrapa con la bolsa del pico después de zambullirse.","habitat":"Costas, bahías, manglares y bocas de ríos y canales.","sw":["#8C8A86","#F2EBD2","#5A4A3A"],"photos":[{"img":"../cartagena/fotos/pelecanusIR.jpg","mini":"../cartagena/fotos/mini/pelecanusIR.jpg","ind":"Adulto en vuelo sobre el mar","place":"Islas del Rosario y Barú"},{"img":"../cartagena/fotos/pelecanusIR2.jpg","mini":"../cartagena/fotos/mini/pelecanusIR2.jpg","ind":"Despegando del agua","place":"Islas del Rosario y Barú"},{"img":"../cartagena/fotos/pelecanus2.jpg","mini":"../cartagena/fotos/mini/pelecanus2.jpg","ind":"Joven en vuelo, pardo de cabeza a cola","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pelecanus.jpg","mini":"../cartagena/fotos/mini/pelecanus.jpg","ind":"Adulto en aguas someras","place":"Canal del Dique, Bolívar"},{"img":"../cartagena/fotos/pelecanus3.jpg","mini":"../cartagena/fotos/mini/pelecanus3.jpg","ind":"Planeando a ras de la bahía","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pelecanusPicada.jpg","mini":"../cartagena/fotos/mini/pelecanusPicada.jpg","ind":"En picada, con las alas recogidas","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pelecanusZ2.jpg","mini":"../cartagena/fotos/mini/pelecanusZ2.jpg","ind":"Bajando al agua para lanzarse","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pelecanusZ.jpg","mini":"../cartagena/fotos/mini/pelecanusZ.jpg","ind":"Zambullida: entra al agua con las alas hacia atrás","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pelecanusIR3.jpg","mini":"../cartagena/fotos/mini/pelecanusIR3.jpg","ind":"Posado en el techo de paja de una cabaña","place":"Islas del Rosario y Barú"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Vuela en fila sobre el agua, rozando las olas. Para pescar sube unos metros y se deja caer en picada; luego flota mientras escurre el agua de la bolsa antes de tragar.","donde":"Bocas del canal, bahía de Cartagena y aguas someras con peces.","id":"pelecanus-occidentalis"}],"en":"Brown Pelican","enAlt":"Pelícano pardo · Alcatraz","g":9},{"k":"Theristicus caudatus","common":"Coclí","alt":"Bandurria · Buff-necked Ibis","sci":"Theristicus caudatus","family":"Threskiornithidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ibis grande con cabeza y cuello color ante, dorso gris, un parche blanco en el ala, vientre negro, patas rojas y un pico largo y curvo. Su nombre viene del grito metálico y fuerte que da en vuelo.","diet":"Insectos, larvas, lombrices, ranas y lagartijas que saca del suelo con el pico.","habitat":"Sabanas, potreros abiertos y bordes de humedales.","sw":["#D9B98A","#7A8086","#1A1A1A","#D2463A"],"photos":[{"img":"../cartagena/fotos/theristicus.jpg","mini":"../cartagena/fotos/mini/theristicus.jpg","ind":"Pareja en un camino de tierra","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en parejas que caminan despacio hundiendo el pico en el suelo. Grita muy fuerte al levantar el vuelo y al amanecer.","donde":"Potreros abiertos y caminos de tierra.","id":"theristicus-caudatus"}],"en":"Buff-necked Ibis","enAlt":"Coclí · Bandurria","g":9},{"k":"Eudocimus albus","common":"Ibis blanco","alt":"Coquito blanco · White Ibis","sci":"Eudocimus albus","family":"Threskiornithidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ibis blanco de tamaño mediano, con la cara desnuda, el pico largo y curvo hacia abajo y las patas de color rojo rosado. En vuelo muestra solo las puntas de las alas negras y lleva el cuello estirado, a diferencia de las garzas. Los jóvenes son pardos con el vientre blanco.","diet":"Cangrejos, camarones, insectos acuáticos y pececillos, que encuentra metiendo el pico en el barro.","habitat":"Manglares, ciénagas costeras, playas fangosas y potreros inundados.","sw":["#F6F4F0","#E2564E","#141414"],"photos":[{"img":"../cartagena/fotos/eudocimus.jpg","mini":"../cartagena/fotos/mini/eudocimus.jpg","ind":"Pareja en vuelo: cuerpo blanco, puntas de las alas negras y pico rojo curvo","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en bandadas que se alimentan caminando en el barro y vuelan en fila o en V, alternando aleteos y planeos cortos.","donde":"Orillas fangosas y manglares; desde el paseo se ve sobre todo cuando pasa volando al atardecer.","id":"eudocimus-albus"}],"en":"White Ibis","enAlt":"Ibis blanco · Coquito blanco","g":9},{"k":"Phimosus infuscatus","common":"Ibis de cara roja","alt":"Coquito · Bare-faced Ibis","sci":"Phimosus infuscatus","family":"Threskiornithidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ibis negro con brillo verdoso, cara desnuda rojiza y un pico largo y curvo del mismo color. Anda en parejas o grupos que caminan despacio por el lodo.","diet":"Larvas, lombrices, caracoles e insectos que saca hundiendo el pico en el barro o en el pasto húmedo.","habitat":"Humedales, potreros encharcados y orillas de lagunas. Se ha vuelto cada vez más frecuente en los humedales de la Sabana.","sw":["#1E2622","#3E5A4B","#C7656B"],"photos":[{"img":"../bogota/fotos/phimosus2.jpg","mini":"../bogota/fotos/mini/phimosus2.jpg","ind":"Grupo en el humedal, uno abriendo las alas","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/phimosus.jpg","mini":"../bogota/fotos/mini/phimosus.jpg","ind":"Pareja buscando comida en el humedal","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/phimosus3.jpg","mini":"../bogota/fotos/mini/phimosus3.jpg","ind":"Posado en lo alto de un sauce","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/phimosusVuelo.jpg","mini":"../bogota/fotos/mini/phimosusVuelo.jpg","ind":"Pareja en vuelo rasante sobre el agua","place":"Humedal de Córdoba, Bogotá"},{"img":"../bogota/fotos/phimosus4.jpg","mini":"../bogota/fotos/mini/phimosus4.jpg","ind":"Abriendo las alas: se ve el brillo azul y verde","place":"Humedal de Córdoba, Bogotá"},{"img":"../bogota/fotos/phimosus5.jpg","mini":"../bogota/fotos/mini/phimosus5.jpg","ind":"Descansando en un arbusto sobre el humedal","place":"Humedal de Córdoba, Bogotá"},{"img":"../bogota/fotos/phimosusSS.jpg","mini":"../bogota/fotos/mini/phimosusSS.jpg","ind":"Dos ibis abriendo las alas sobre troncos caídos, junto a una torcaza","place":"Hacienda San Simón, Guaymaral"},{"img":"../cafetera/fotos/phimosus.jpg","mini":"../cafetera/fotos/mini/phimosus.jpg","ind":"Posado en una rama","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina despacio en parejas o grupos, metiendo el pico curvo en el barro. Vuela en fila con el cuello estirado.","donde":"Bordes del humedal y potreros encharcados, sobre todo después de las lluvias. Todo el año.","id":"phimosus-infuscatus"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas o grupos que caminan metiendo el pico en el barro.","donde":"Orillas húmedas y potreros encharcados.","id":"phimosus-infuscatus"}],"en":"Bare-faced Ibis","enAlt":"Ibis de cara roja · Coquito","g":9},{"k":"Cathartes aura","common":"Gallinazo cabecirrojo","alt":"Guala · Turkey Vulture","sci":"Cathartes aura","family":"Cathartidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave grande y negra con la cabeza desnuda y roja. En vuelo se reconoce a lo lejos: alas en forma de V abierta, con la mitad posterior plateada, y un balanceo de lado a lado sin casi aletear.","diet":"Carroña. A diferencia de casi todas las aves, tiene un olfato excelente: detecta el olor de un animal muerto bajo el follaje, desde el aire.","habitat":"Cielos abiertos sobre potreros, bosques y zonas rurales, desde el nivel del mar hasta los páramos. Hay una población residente en Colombia; en el invierno del norte llegan además aves migratorias desde Norteamérica.","sw":["#1B1A1C","#9EA2A6","#A8322E"],"photos":[{"img":"../bogota/fotos/cathartes.jpg","mini":"../bogota/fotos/mini/cathartes.jpg","ind":"Planeando sobre la hacienda","place":"Hacienda San Simón, Guaymaral"},{"img":"../cartagena/fotos/cathartesMG.jpg","mini":"../cartagena/fotos/mini/cathartesMG.jpg","ind":"Planeando: alas en V con la mitad plateada","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Pasa horas planeando en las corrientes de aire caliente casi sin mover las alas, buscando por olfato. Duerme en grupo en árboles altos y por la mañana abre las alas al sol para calentarse. Es silenciosa: solo sisea.","donde":"En el cielo sobre los potreros, a media mañana y en la tarde, cuando hay corrientes cálidas. Todo el año.","id":"cathartes-aura"},{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Planea durante horas en las corrientes de aire caliente, buscando comida por el olfato.","donde":"Cielo sobre la bahía a media mañana y en la tarde.","id":"cathartes-aura"}],"en":"Turkey Vulture","enAlt":"Gallinazo cabecirrojo · Guala","g":10},{"k":"Coragyps atratus","common":"Gallinazo negro","alt":"Chulo · Zamuro · Black Vulture","sci":"Coragyps atratus","family":"Cathartidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Ave grande y negra, con la cabeza desnuda y gris oscura. En vuelo se distingue del gallinazo cabecirrojo por la cola corta y cuadrada y por una mancha blanca en la punta de cada ala; aletea más seguido y planea con las alas casi rectas.","diet":"Carroña. A diferencia del cabecirrojo, casi no tiene olfato y encuentra la comida mirando, a menudo siguiendo a los cabecirrojos; también come basura y frutos caídos.","habitat":"Ciudades, basureros, potreros y bordes de carretera, desde el nivel del mar hasta unos 2.800 m.","sw":["#141414","#5A5A5A","#E8E8E4"],"photos":[{"img":"../bogota/fotos/coragyps.jpg","mini":"../bogota/fotos/mini/coragyps.jpg","ind":"Despegando entre los árboles, con las puntas de las alas blancas","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Muy sociable: duerme y come en grupos grandes y se impone en la carroña por número. Se asolea con las alas abiertas en las mañanas frías.","donde":"Árboles altos y potreros de la hacienda; en el cielo, en grupos que planean juntos.","id":"coragyps-atratus"}],"en":"Black Vulture","enAlt":"Gallinazo negro · Chulo · Zamuro","g":10},{"k":"Buteo platypterus","common":"Gavilán aliancho","alt":"Gavilán pollero aliancho · Broad-winged Hawk","sci":"Buteo platypterus","family":"Accipitridae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Rapaz mediana y compacta. El adulto tiene el pecho barrado de rufo y la cola con bandas anchas blancas y negras. Caza al acecho desde una percha dentro del bosque o en bordes.","diet":"Ranas, lagartijas, roedores, insectos grandes y polluelos. En invernada aprovecha bordes y potreros arbolados.","habitat":"Cría en bosques del este de Norteamérica. Inverna en bosques y bordes de los Andes, desde Colombia hasta Bolivia.","sw":["#6B4A32","#B5683F","#EFE6D8","#2A2420"],"photos":[{"img":"../bogota/fotos/buteo.jpg","mini":"../bogota/fotos/mini/buteo.jpg","ind":"Adulto, pecho barrado de rufo","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Caza al acecho desde una percha a media altura y se lanza sobre la presa. En invernada anda solo; en migración viaja en bandadas enormes que suben en espiral en las corrientes de aire caliente.","donde":"Perchas en bordes de arboledas y cercas vivas. En mañanas soleadas de octubre y marzo, mira al cielo: pueden pasar bandadas en vuelo.","id":"buteo-platypterus"}],"en":"Broad-winged Hawk","enAlt":"Gavilán aliancho · Gavilán pollero aliancho","g":11},{"k":"Rupornis magnirostris","common":"Gavilán caminero","alt":"Busardo caminero · Roadside Hawk","sci":"Rupornis magnirostris","family":"Accipitridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Gavilán pequeño y gris, con el pecho y el vientre barrados de gris y canela, ojos amarillo pálido y patas y base del pico amarillo anaranjado. Es el gavilán más común de Colombia.","diet":"Lagartijas, ratones, insectos grandes, ranas y pájaros pequeños. En San Simón lo fotografiamos con un pájaro recién cazado: al comer abre las alas y la cola sobre la presa, un gesto llamado «mantear» con el que la esconde de otros depredadores.","habitat":"Bordes de bosque, potreros con árboles, cercas vivas y bordes de carretera, desde el nivel del mar hasta unos 2.800 m.","sw":["#5B5E66","#B48A6A","#E7A03A","#E8D46A"],"photos":[{"img":"../bogota/fotos/rupornisPresa.jpg","mini":"../bogota/fotos/mini/rupornisPresa.jpg","ind":"Con un pájaro recién cazado en las garras, abriendo las alas para cubrir la presa","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rupornis.jpg","mini":"../bogota/fotos/mini/rupornis.jpg","ind":"Adulto posado en el yarumo sembrado en la hacienda","place":"Hacienda San Simón, Guaymaral"},{"img":"../barichara/fotos/rupornis.jpg","mini":"../barichara/fotos/mini/rupornis.jpg","ind":"Adulto entre el follaje, mirando hacia abajo","place":"Barichara, Santander"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Caza al acecho desde postes y ramas a media altura, muy quieto, y se deja caer sobre la presa. Es ruidoso: su grito es un «kiiiii-ah» quejumbroso que repite a menudo.","donde":"Postes, cercas vivas y árboles aislados junto a potreros. Todo el año.","id":"rupornis-magnirostris"},{"l":"barichara","nom":"Barichara","hab":"Caza al acecho desde ramas a media altura, muy quieto, y se deja caer sobre la presa. Es ruidoso: su grito es un «kiiiii-ah» quejumbroso que repite a menudo.","donde":"Árboles frondosos y cercas vivas junto a potreros y caminos.","id":"rupornis-magnirostris"}],"en":"Roadside Hawk","enAlt":"Gavilán caminero · Busardo caminero","g":11},{"k":"Rostrhamus sociabilis","common":"Gavilán caracolero","alt":"Caracolero · Snail Kite","sci":"Rostrhamus sociabilis","family":"Accipitridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El juvenil, como el de la foto, es pardo con rayas blancas y una ceja clara. El macho adulto es gris pizarra oscuro, con la cara y las patas rojas. Su pico delgado y muy ganchudo es una herramienta especializada para sacar al caracol de su concha.","diet":"Casi exclusivamente caracoles de agua dulce del género Pomacea, que caza en vuelo bajo sobre la ciénaga.","habitat":"Ciénagas y humedales de agua dulce con caracoles. Si el humedal se seca o se contamina, desaparece.","sw":["#5A4636","#F2EDE4","#3E4652","#E2843C"],"photos":[{"img":"../cartagena/fotos/rostrhamus.jpg","mini":"../cartagena/fotos/mini/rostrhamus.jpg","ind":"Juvenil, pardo y rayado, con ceja blanca","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Vuela bajo y lento sobre la ciénaga, mirando hacia abajo. Cuando agarra un caracol, se lo lleva a una percha favorita, donde se acumulan las conchas vacías.","donde":"Perchas a la orilla de la ciénaga; busque montoncitos de conchas de caracol debajo.","id":"rostrhamus-sociabilis"}],"en":"Snail Kite","enAlt":"Gavilán caracolero · Caracolero","g":11},{"k":"Elanus leucurus","common":"Gavilán maromero","alt":"Elanio coliblanco · White-tailed Kite","sci":"Elanus leucurus","family":"Accipitridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Rapaz gris pálida y blanca, con hombros negros y ojos rojos. El nombre «maromero» viene de su costumbre de quedarse suspendido en el aire, aleteando en el mismo punto, mientras busca presas.","diet":"Sobre todo roedores pequeños; también lagartijas e insectos grandes.","habitat":"Potreros, pastizales y campos abiertos con árboles aislados para posarse. Controla poblaciones de ratones en fincas.","sw":["#CFD3D6","#F7F7F5","#1E1E1E","#B23A2E"],"photos":[{"img":"../bogota/fotos/elanus.jpg","mini":"../bogota/fotos/mini/elanus.jpg","ind":"Adulto posado","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Se cierne en el aire aleteando en el mismo punto, con las patas colgando, antes de dejarse caer sobre un ratón. Esas «maromas» le dan el nombre.","donde":"Árboles secos aislados y postes en los potreros; en el aire sobre el pasto alto. Tardes. Todo el año.","id":"elanus-leucurus"}],"en":"White-tailed Kite","enAlt":"Gavilán maromero · Elanio coliblanco","g":11},{"k":"Buteogallus meridionalis","common":"Gavilán sabanero","alt":"Busardo sabanero · Savanna Hawk","sci":"Buteogallus meridionalis","family":"Accipitridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Rapaz grande de color canela rojizo con barrado fino, patas largas y amarillas, y cola negra con una banda blanca. En vuelo, sus alas rojizas con puntas negras se ven desde lejos.","diet":"Lagartijas, serpientes, ranas, roedores, cangrejos e insectos grandes. Sigue a las quemas y a los tractores para atrapar lo que huye.","habitat":"Sabanas, potreros y bordes de ciénagas de tierras bajas.","sw":["#B8663A","#1A1A1A","#E8C83A"],"photos":[{"img":"../cartagena/fotos/buteogallus.jpg","mini":"../cartagena/fotos/mini/buteogallus.jpg","ind":"Pareja posada en un matorral","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/buteogallus2.jpg","mini":"../cartagena/fotos/mini/buteogallus2.jpg","ind":"Despegando: alas rojizas y cola con banda blanca","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Pasa mucho tiempo posado en postes, matorrales o en el suelo. Camina con sus patas largas para cazar insectos y lagartijas.","donde":"Postes y matorrales en potreros abiertos.","id":"buteogallus-meridionalis"}],"en":"Savanna Hawk","enAlt":"Gavilán sabanero · Busardo sabanero","g":11},{"k":"Pandion haliaetus","common":"Águila pescadora","alt":"Osprey","sci":"Pandion haliaetus","family":"Pandionidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Rapaz grande, parda por encima y blanca por debajo, con un antifaz oscuro que cruza el ojo. Es la única rapaz que se alimenta casi solo de peces: tiene espinas en la planta de las patas y puede girar un dedo hacia atrás para sujetar presas resbalosas.","diet":"Peces vivos, que atrapa lanzándose en picada con las patas por delante y a veces hundiéndose por completo.","habitat":"Ciénagas, ríos, lagunas, embalses y costas en casi todo el mundo.","sw":["#4A3828","#F4F2EC","#1E1A16"],"photos":[{"img":"../pijino/fotos/pandion.jpg","mini":"../pijino/fotos/mini/pandion.jpg","ind":"Con un pescado en las garras","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/pandion2.jpg","mini":"../pijino/fotos/mini/pandion2.jpg","ind":"Secándose con las alas entreabiertas","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Patrulla la ciénaga en vuelo alto, se cierne un momento y se lanza en picada con las patas por delante. Después se lleva el pescado a una percha alta, sosteniéndolo de cabeza hacia adelante para cortar el viento.","donde":"Árboles secos y altos junto al agua, de octubre a abril.","id":"pandion-haliaetus"}],"en":"Osprey","enAlt":"Águila pescadora","g":11},{"k":"Chloroceryle amazona","common":"Martín pescador amazónico","alt":"Amazon Kingfisher","sci":"Chloroceryle amazona","family":"Alcedinidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Verde oscuro brillante por encima, con collar blanco y un pico largo y pesado. El macho tiene una banda castaña en el pecho; la hembra, verde. Es el más grande de los martines pescadores verdes.","diet":"Peces pequeños y medianos que caza zambulléndose desde ramas bajas.","habitat":"Orillas de ciénagas, caños y ríos con ramas sobre el agua.","sw":["#1E5A4A","#F4F4F0","#151515"],"photos":[{"img":"../pijino/fotos/amazona.jpg","mini":"../pijino/fotos/mini/amazona.jpg","ind":"Posado sobre el agua, con la cresta levantada","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/amazona2.jpg","mini":"../pijino/fotos/mini/amazona2.jpg","ind":"A contraluz al amanecer","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Más callado que el martín grande; vigila desde ramas bajas y vuela rasante sobre el agua.","donde":"Ramas bajas sobre la orilla de caños y ciénaga.","id":"chloroceryle-amazona"}],"en":"Amazon Kingfisher","enAlt":"Martín pescador amazónico","g":12},{"k":"Megaceryle torquata","common":"Martín pescador grande","alt":"Martín gigante · Ringed Kingfisher","sci":"Megaceryle torquata","family":"Alcedinidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El martín pescador más grande de América: dorso gris azulado, collar blanco, cresta despeinada y vientre castaño. La hembra, como la de la foto, tiene además una banda gris azulada que cruza el pecho.","diet":"Peces, que atrapa lanzándose de cabeza desde una percha o después de cernirse en el aire.","habitat":"Ciénagas, ríos anchos, lagunas y manglares. Anida en túneles que excava en barrancos de tierra.","sw":["#5A7A9A","#F4F4F0","#A84E2A"],"photos":[{"img":"../pijino/fotos/torquata.jpg","mini":"../pijino/fotos/mini/torquata.jpg","ind":"Hembra, con la banda azul en el pecho","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/torquata2.jpg","mini":"../pijino/fotos/mini/torquata2.jpg","ind":"Vigilando el agua desde una rama seca","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Ruidoso: vuela sobre el agua dando un traqueteo fuerte. Vigila desde ramas altas y se lanza de cabeza.","donde":"Ramas secas y altas sobre la ciénaga y los caños.","id":"megaceryle-torquata"}],"en":"Ringed Kingfisher","enAlt":"Martín pescador grande · Martín gigante","g":12},{"k":"Momotus subrufescens","common":"Barranquero","alt":"Momoto · Whooping Motmot","sci":"Momotus subrufescens","family":"Momotidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Corona con un aro azul turquesa, antifaz negro, dorso verde y pecho canela. Su cola larga termina en dos «raquetas»: las barbas de las plumas centrales se desprenden y dejan solo el astil desnudo antes de la punta. Su nombre viene de los barrancos donde excava túneles de más de un metro para anidar.","diet":"Insectos grandes, arañas, lagartijas y ranas pequeñas que caza desde una percha; también frutos.","habitat":"Bosque seco, cañadas sombreadas, cafetales y bordes de bosque, desde tierras bajas hasta unos 1.500 m.","sw":["#3CC2E0","#4E9A6E","#C27A45","#141414"],"photos":[{"img":"../barichara/fotos/momotus.jpg","mini":"../barichara/fotos/mini/momotus.jpg","ind":"Adulto en una rama con líquenes","place":"Barichara, Santander"},{"img":"../barichara/fotos/momotus2.jpg","mini":"../barichara/fotos/mini/momotus2.jpg","ind":"De frente, con el pecho canela y la cola de raqueta","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Se queda inmóvil largo rato en ramas bajas y sombreadas, balanceando la cola de lado a lado como un péndulo. Canta al amanecer un «u-dut» grave y doble, que es la mejor forma de encontrarlo.","donde":"Cañadas sombreadas y bordes de bosque seco alrededor del pueblo, temprano en la mañana.","id":"momotus-subrufescens"}],"en":"Whooping Motmot","enAlt":"Barranquero · Momoto","g":12},{"k":"Melanerpes rubricapillus","common":"Carpintero habado","alt":"Carpintero coronirrojo · Red-crowned Woodpecker","sci":"Melanerpes rubricapillus","family":"Picidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Dorso barrado en blanco y negro, cara y partes inferiores beige, y la corona y la nuca rojas en el macho. Es de los pocos carpinteros que se adapta bien a la ciudad.","diet":"Insectos y larvas que saca de la madera, frutos y néctar.","habitat":"Parques, jardines, manglares y bordes de bosque seco; usa postes y árboles secos para anidar.","sw":["#D9372A","#1C1C1C","#D8CFB4"],"photos":[{"img":"../cartagena/fotos/melanerpesMG.jpg","mini":"../cartagena/fotos/mini/melanerpesMG.jpg","ind":"Macho en un poste de concreto","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/melanerpesMG4.jpg","mini":"../cartagena/fotos/mini/melanerpesMG4.jpg","ind":"Trepando un tronco, con la espalda barrada","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/melanerpesMG3.jpg","mini":"../cartagena/fotos/mini/melanerpesMG3.jpg","ind":"En una rama seca, con la nuca naranja","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/melanerpesMG2.jpg","mini":"../cartagena/fotos/mini/melanerpesMG2.jpg","ind":"De espaldas contra el cielo","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../barichara/fotos/melanerpes.jpg","mini":"../barichara/fotos/mini/melanerpes.jpg","ind":"Macho picando una rama","place":"Barichara, Santander"},{"img":"../barichara/fotos/melanerpes2.jpg","mini":"../barichara/fotos/mini/melanerpes2.jpg","ind":"Macho, con el dorso barrado a la vista","place":"Barichara, Santander"},{"img":"../cafetera/fotos/melanerpes.jpg","mini":"../cafetera/fotos/mini/melanerpes.jpg","ind":"Macho en un tronco","place":"Zona Cafetera"},{"img":"../cafetera/fotos/melanerpes2.jpg","mini":"../cafetera/fotos/mini/melanerpes2.jpg","ind":"Macho en el comedero de guadua","place":"Zona Cafetera"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Ruidoso, con un llamado de traqueteo; picotea postes y ramas secas para buscar larvas y excavar el nido.","donde":"Postes y árboles del paseo.","id":"melanerpes-rubricapillus"},{"l":"barichara","nom":"Barichara","hab":"Ruidoso, con un llamado de traqueteo. Picotea ramas secas y postes para buscar larvas y para excavar su nido.","donde":"Árboles secos, postes de madera y ramas muertas de los jardines.","id":"melanerpes-rubricapillus"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Ruidoso, picotea ramas secas y postes.","donde":"Troncos, postes y ramas muertas.","id":"melanerpes-rubricapillus"}],"en":"Red-crowned Woodpecker","enAlt":"Carpintero habado · Carpintero coronirrojo","g":13},{"k":"Caracara cheriway","common":"Caracara copetón","alt":"Carancho · Crested Caracara","sci":"Caracara cheriway","family":"Falconidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Halcón grande y de patas largas, con capucha negra, cara roja o anaranjada desnuda, cuello blanco y pecho barrado. En vuelo muestra un parche claro en la punta de cada ala y la cola blanca con una banda negra.","diet":"Carroña, peces moribundos, tortugas pequeñas, insectos y lo que encuentre; también roba presas a otras aves.","habitat":"Sabanas, potreros, playas y orillas abiertas de tierras bajas.","sw":["#1E1A16","#E05A3A","#F2EEE4"],"photos":[{"img":"../cartagena/fotos/caracara.jpg","mini":"../cartagena/fotos/mini/caracara.jpg","ind":"En vuelo visto desde abajo: cara anaranjada, cuello barrado y puntas de las alas claras","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../pijino/fotos/caracara.jpg","mini":"../pijino/fotos/mini/caracara.jpg","ind":"Posado en un tronco seco","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Camina mucho por el suelo y planea bajo sobre playas y potreros buscando comida; a menudo sigue a los gallinazos hasta la carroña.","donde":"Cielo sobre la bahía y potreros abiertos.","id":"caracara-cheriway"},{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Camina por el suelo como un gallinazo y se posa en lo alto de troncos secos. Echa la cabeza hacia atrás cuando grita.","donde":"Troncos secos y potreros abiertos junto a la ciénaga.","id":"caracara-cheriway"}],"en":"Crested Caracara","enAlt":"Caracara copetón · Carancho","g":14},{"k":"Milvago chimachima","common":"Pigua","alt":"Caracara chimachima · Yellow-headed Caracara","sci":"Milvago chimachima","family":"Falconidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pariente de los halcones. Cabeza y partes inferiores color crema, una línea oscura detrás del ojo y dorso pardo oscuro. Es oportunista y poco tímido.","diet":"Carroña, insectos, lagartijas, frutos y garrapatas, que les saca directamente del lomo al ganado y a los chigüiros.","habitat":"Potreros con árboles, bordes de carretera y zonas abiertas de tierras bajas; se ha ido extendiendo hacia zonas más altas.","sw":["#E9DFC8","#4A3626","#1E1A16"],"photos":[{"img":"../cartagena/fotos/milvagoAR.jpg","mini":"../cartagena/fotos/mini/milvagoAR.jpg","ind":"Adulto sobre un matorral con enredaderas, con la cola barrada","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/milvago.jpg","mini":"../cartagena/fotos/mini/milvago.jpg","ind":"Adulto, cabeza color crema","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/milvago2.jpg","mini":"../cartagena/fotos/mini/milvago2.jpg","ind":"En vuelo sobre la bahía: parches claros en las alas","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../pijino/fotos/milvago.jpg","mini":"../pijino/fotos/mini/milvago.jpg","ind":"Adulto posado en una rama","place":"Ciénaga de Pijiño, Magdalena"},{"img":"../pijino/fotos/milvagoJuv.jpg","mini":"../pijino/fotos/mini/milvagoJuv.jpg","ind":"Juvenil en vuelo, pardo y rayado","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Confiado y oportunista: se posa sobre el ganado para quitarle garrapatas y aprovecha cualquier comida fácil. Su grito es un chillido agudo y quejumbroso.","donde":"Árboles aislados y cercas junto a potreros con ganado.","id":"milvago-chimachima"},{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Confiado y oportunista; se posa sobre el ganado para quitarle garrapatas. Su grito es un chillido agudo y quejumbroso.","donde":"Árboles aislados y matorrales junto a potreros.","id":"milvago-chimachima"}],"en":"Yellow-headed Caracara","enAlt":"Pigua · Caracara chimachima","g":14},{"k":"Ara ararauna","common":"Guacamaya azul y amarilla","alt":"Guacamayo azulamarillo · Blue-and-yellow Macaw","sci":"Ara ararauna","family":"Psittacidae","iucn":"LC","mig":false,"dom":true,"feral":true,"conf":"media","desc":"Guacamaya grande, de casi 90 cm con la cola: azul turquesa por encima, amarillo dorado por debajo, cara blanca con finas líneas negras y un pico negro enorme capaz de partir nueces muy duras.","diet":"Semillas, nueces, frutos de palmas y flores. En la ciudad come frutos de almendros, mangos y palmas ornamentales.","habitat":"En estado silvestre, selvas húmedas, palmares de moriche y bordes de ríos de tierras bajas. En Cartagena, el grupo asilvestrado vive en la zona del puerto y se mueve por Manga y la bahía.","sw":["#1C7FC2","#F2B52A","#F4F4F0","#151515"],"photos":[{"img":"../cartagena/fotos/ara.jpg","mini":"../cartagena/fotos/mini/ara.jpg","ind":"Pareja en un balcón","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/araMG.jpg","mini":"../cartagena/fotos/mini/araMG.jpg","ind":"En vuelo sobre Manga junto a otra guacamaya de plumaje verde y azul, probablemente un híbrido también escapado de cautiverio","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en pareja o en grupo, se posa en balcones y árboles altos y cruza la bahía en vuelo con gritos muy fuertes, que se oyen antes de verlas.","donde":"Cielo sobre la bahía entre el puerto y Manga, y balcones y palmas del paseo peatonal, sobre todo temprano y al atardecer.","id":"ara-ararauna"}],"en":"Blue-and-yellow Macaw","enAlt":"Guacamaya azul y amarilla · Guacamayo azulamarillo","g":15},{"k":"Eupsittula pertinax","common":"Perico carisucio","alt":"Cotorra carisucia · Brown-throated Parakeet","sci":"Eupsittula pertinax","family":"Psittacidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Periquito verde de cola larga y puntiaguda, con la cara, la garganta y el pecho pardo ocre, como manchados, de ahí lo de «carisucio». Tiene un anillo claro alrededor del ojo y el pico oscuro.","diet":"Frutos, semillas, flores y néctar; frecuenta árboles de mango, almendro y cactus en flor.","habitat":"Zonas secas de la costa, matorrales, manglares, parques y barrios arborizados.","sw":["#3E9A3A","#9C6A3A","#C8C86A"],"photos":[{"img":"../cartagena/fotos/eupsittula2.jpg","mini":"../cartagena/fotos/mini/eupsittula2.jpg","ind":"Pareja en ramas secas","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/eupsittula.jpg","mini":"../cartagena/fotos/mini/eupsittula.jpg","ind":"Adulto, con la cara y el pecho pardos","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en parejas o bandadas que chillan al volar. Se mueve trepando por las ramas con el pico y las patas.","donde":"Copas de árboles del paseo y de los parques, al amanecer y al atardecer.","id":"eupsittula-pertinax"}],"en":"Brown-throated Parakeet","enAlt":"Perico carisucio · Cotorra carisucia","g":15},{"k":"Brotogeris jugularis","common":"Periquito bronceado","alt":"Perico barbinaranja · Orange-chinned Parakeet","sci":"Brotogeris jugularis","family":"Psittacidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Periquito verde, pequeño, con una mancha naranja en la barbilla, hombros color bronce, pico pálido y anillo blanco alrededor del ojo. Anda en parejas y grupos ruidosos.","diet":"Frutos, semillas, flores y néctar de árboles como el ceibo y el guamo.","habitat":"Bosque seco, potreros arbolados, pueblos y jardines.","sw":["#5DB43A","#E8823A","#9C7A3A"],"photos":[{"img":"../cartagena/fotos/brotogeris.jpg","mini":"../cartagena/fotos/mini/brotogeris.jpg","ind":"Adulto en una rama seca","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/brotogeris2.jpg","mini":"../cartagena/fotos/mini/brotogeris2.jpg","ind":"Pareja","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/brotogerisMG2.jpg","mini":"../cartagena/fotos/mini/brotogerisMG2.jpg","ind":"Entre las hojas de un almendro, con el hombro pardo","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/brotogerisMG.jpg","mini":"../cartagena/fotos/mini/brotogerisMG.jpg","ind":"En ramas secas, con la mancha naranja del mentón","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Anda en parejas o grupos ruidosos que chillan al volar. Se esconden bien entre el follaje verde.","donde":"Copas de árboles en flor o con frutos, sobre todo en la mañana.","id":"brotogeris-jugularis"}],"en":"Orange-chinned Parakeet","enAlt":"Periquito bronceado · Perico barbinaranja","g":15},{"k":"Forpus conspicillatus","common":"Periquito de anteojos","alt":"Spectacled Parrotlet","sci":"Forpus conspicillatus","family":"Psittacidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Diminuto loro verde, de unos 12 cm. El macho tiene un anillo azul alrededor del ojo, como unas gafas, y azul en las alas; la hembra es toda verde.","diet":"Semillas de pastos y frutos pequeños.","habitat":"Zonas abiertas con árboles, cafetales y jardines.","sw":["#7CC85A","#3A6AD8"],"photos":[{"img":"../cafetera/fotos/forpus.jpg","mini":"../cafetera/fotos/mini/forpus.jpg","ind":"Macho, con el anillo azul alrededor del ojo","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"En bandadas pequeñas y parlanchinas que comen en el suelo y en arbustos.","donde":"Cercas, potreros con semillas y jardines.","id":"forpus-conspicillatus"}],"en":"Spectacled Parrotlet","enAlt":"Periquito de anteojos","g":15},{"k":"Furnarius leucopus","common":"Hornero patiamarillo","alt":"Pale-legged Hornero","sci":"Furnarius leucopus","family":"Furnariidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Rojizo por encima, con ceja blanca, garganta blancuzca, pecho ante y patas pálidas. Su nombre viene del nido: una bola de barro con forma de horno de leña, que construye en ramas y postes.","diet":"Insectos y larvas que busca caminando en el suelo húmedo.","habitat":"Bordes de ciénagas y caños, potreros con árboles y jardines de tierras bajas.","sw":["#B8653A","#E3D2B0","#F4F0E8"],"photos":[{"img":"../cartagena/fotos/furnarius.jpg","mini":"../cartagena/fotos/mini/furnarius.jpg","ind":"Adulto en una rama","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Camina por el suelo con paso firme, levantando la cola. La pareja canta a dúo un trino fuerte y acelerado.","donde":"Suelo húmedo a la orilla de caños y bajo los árboles; busque su nido de barro en ramas y postes.","id":"furnarius-leucopus"}],"en":"Pale-legged Hornero","enAlt":"Hornero patiamarillo","g":16},{"k":"Pyrocephalus rubinus","common":"Atrapamoscas pechirrojo","alt":"Petirrojo · Vermilion Flycatcher","sci":"Pyrocephalus rubinus","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es inconfundible: corona y partes inferiores rojo encendido, antifaz y dorso pardo oscuro. La hembra es gris parda, con la garganta blanca, el pecho finamente rayado y el vientre salmón.","diet":"Insectos que atrapa en vuelos cortos desde una percha baja, a menudo bajando al suelo.","habitat":"Zonas abiertas y secas con árboles dispersos, potreros, cercas y jardines.","sw":["#E5341F","#4A3A33","#E8956A"],"photos":[{"img":"../barichara/fotos/pyroM.jpg","mini":"../barichara/fotos/mini/pyroM.jpg","ind":"Macho entre barbas de viejo","place":"Barichara, Santander"},{"img":"../barichara/fotos/pyroF.jpg","mini":"../barichara/fotos/mini/pyroF.jpg","ind":"Hembra, con el vientre salmón","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Caza desde perchas bajas y expuestas y vuelve casi siempre al mismo sitio. En celo, el macho sube aleteando con las plumas erizadas mientras canta y luego se deja caer.","donde":"Ramas bajas y cercas en zonas abiertas, sobre todo con barbas de viejo.","id":"pyrocephalus-rubinus"}],"en":"Vermilion Flycatcher","enAlt":"Atrapamoscas pechirrojo · Petirrojo","g":17},{"k":"Pitangus sulphuratus","common":"Bichofué","alt":"Bienteveo grande · Great Kiskadee","sci":"Pitangus sulphuratus","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Atrapamoscas grande y llamativo: cabeza negra con una banda blanca ancha sobre el ojo, garganta blanca, vientre amarillo intenso y alas y cola rojizas. Su nombre es la imitación de su grito: «bi-cho-fué».","diet":"De todo: insectos que caza al vuelo, lagartijas, pececitos que saca del agua como un martín pescador, frutos y hasta comida que encuentra en la ciudad.","habitat":"Pueblos, parques, orillas de agua, potreros y bordes de bosque de tierras bajas y medias.","sw":["#151515","#F4F2EA","#F2C82A","#A8592E"],"photos":[{"img":"../cartagena/fotos/pitangus.jpg","mini":"../cartagena/fotos/mini/pitangus.jpg","ind":"Adulto posado al atardecer","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pitangus2.jpg","mini":"../cartagena/fotos/mini/pitangus2.jpg","ind":"En vuelo, con las alas rojizas abiertas","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pitangus3.jpg","mini":"../cartagena/fotos/mini/pitangus3.jpg","ind":"Lanzándose sobre el andén","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/pitangus4.jpg","mini":"../cartagena/fotos/mini/pitangus4.jpg","ind":"En vuelo, visto desde arriba","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Ruidoso y atrevido: grita su nombre desde antenas, cables y árboles, y defiende su territorio incluso contra aves más grandes. Se lanza en picada al agua o al suelo para atrapar presas.","donde":"Árboles del paseo, cables y orillas de la bahía; se oye antes de verse.","id":"pitangus-sulphuratus"}],"en":"Great Kiskadee","enAlt":"Bichofué · Bienteveo grande","g":17},{"k":"Elaenia flavogaster","common":"Elaenia copetona","alt":"Bobito copetón · Yellow-bellied Elaenia","sci":"Elaenia flavogaster","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Mosquero pequeño, gris oliva, con dos barras blancas en el ala, el vientre amarillo pálido y un copete desordenado que levanta como un penacho. Es ruidoso: repite un «uí-birr» ronco.","diet":"Insectos y muchos frutos pequeños; es una de las aves que más ayuda a dispersar semillas en los rastrojos.","habitat":"Rastrojos, cercas vivas, potreros con árboles y jardines de tierra cálida y templada.","sw":["#7A7A62","#E3DE9A","#EDEDE6"],"photos":[{"img":"../barichara/fotos/elaenia.jpg","mini":"../barichara/fotos/mini/elaenia.jpg","ind":"Con el copete erizado, en un espino","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Inquieta y vocal; se posa a la vista en arbustos y espinos y levanta el copete cuando canta o se alarma.","donde":"Espinos, cercas vivas y arbustos con frutos pequeños.","id":"elaenia-flavogaster"}],"en":"Yellow-bellied Elaenia","enAlt":"Elaenia copetona · Bobito copetón","g":17},{"k":"Contopus virens","common":"Pibí oriental","alt":"Eastern Wood-Pewee","sci":"Contopus virens","family":"Tyrannidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Atrapamoscas gris pardo con dos barras claras en el ala, sin anillo ocular y con la cabeza algo picuda. Casi idéntico al pibí occidental; se distinguen por el canto, un «pi-iii-uí» silbado y lastimero que le da su nombre. Se posa erguido en ramas secas y expuestas, y vuelve a la misma percha tras cada captura.","diet":"Insectos voladores (moscas, abejas, polillas) que atrapa en vuelos cortos desde la percha.","habitat":"Cría en bosques de Norteamérica. Inverna en bordes de bosque y claros con árboles altos en el norte de Suramérica.","sw":["#6E6A58","#9C9886","#E4E1D2"],"photos":[{"img":"../bogota/fotos/contopus.jpg","mini":"../bogota/fotos/mini/contopus.jpg","ind":"Adulto","place":"Lugar por confirmar"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Se posa erguido y quieto en una rama seca, sale en un vuelo corto a atrapar un insecto y regresa casi siempre a la misma percha.","donde":"Ramas muertas y expuestas en lo alto de árboles, en bordes y claros. De septiembre a abril.","id":"contopus"}],"en":"Eastern Wood-Pewee","enAlt":"Pibí oriental","g":17},{"k":"Machetornis rixosa","common":"Sirirí bueyero","alt":"Atrapamoscas ganadero · Cattle Tyrant","sci":"Machetornis rixosa","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pardo grisáceo por encima y amarillo por debajo, con patas largas. A diferencia de casi todos los atrapamoscas, camina y corre por el suelo. Tiene una pequeña mancha roja escondida en la corona.","diet":"Insectos que espanta el ganado al caminar; por eso se monta sobre el lomo de vacas y caballos.","habitat":"Potreros, prados, canchas y patios abiertos de tierras bajas y medias.","sw":["#9C9682","#E8D86A"],"photos":[{"img":"../barichara/fotos/machetornis.jpg","mini":"../barichara/fotos/mini/machetornis.jpg","ind":"Caminando en el pasto","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Camina y corre por el suelo como un pájaro de patio y se monta sobre el ganado para cazar los insectos que este espanta.","donde":"Potreros con ganado, prados y canchas.","id":"machetornis-rixosa"}],"en":"Cattle Tyrant","enAlt":"Sirirí bueyero · Atrapamoscas ganadero","g":17},{"k":"Tyrannus melancholicus","common":"Sirirí común","alt":"Tirano tropical · Tropical Kingbird","sci":"Tyrannus melancholicus","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Cabeza gris con antifaz oscuro, dorso oliva, pecho y vientre amarillos y cola parda con una muesca en la punta. Es de las aves más comunes de Colombia y casi siempre se ve en una percha alta y expuesta.","diet":"Insectos que caza en vuelo con salidas cortas desde la percha; también algunos frutos.","habitat":"Cualquier zona abierta con árboles: potreros, pueblos, cables y bordes de bosque.","sw":["#8C9196","#E6D23A","#4A4238"],"photos":[{"img":"../cartagena/fotos/melancholicus.jpg","mini":"../cartagena/fotos/mini/melancholicus.jpg","ind":"Visto desde abajo, con el vientre amarillo","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../barichara/fotos/melancholicus.jpg","mini":"../barichara/fotos/mini/melancholicus.jpg","ind":"Posado en lo alto, con el pecho amarillo","place":"Barichara, Santander"},{"img":"../barichara/fotos/melancholicus2.jpg","mini":"../barichara/fotos/mini/melancholicus2.jpg","ind":"En un cable frente a una pared encalada","place":"Barichara, Santander"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Caza desde perchas altas y vuelve al mismo sitio. Es valiente: persigue a gavilanes y aves mucho más grandes que se acerquen a su nido.","donde":"Ramas altas, cables y postes del paseo.","id":"tyrannus-melancholicus"},{"l":"barichara","nom":"Barichara","hab":"Caza desde perchas altas y vuelve al mismo sitio. Es valiente: persigue a gavilanes y aves mucho más grandes que se acerquen a su nido.","donde":"Ramas altas, cables y postes en zonas abiertas.","id":"tyrannus-melancholicus"}],"en":"Tropical Kingbird","enAlt":"Sirirí común · Tirano tropical","g":17},{"k":"Tyrannus tyrannus","common":"Sirirí norteño","alt":"Tirano oriental · Eastern Kingbird","sci":"Tyrannus tyrannus","family":"Tyrannidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Atrapamoscas elegante: cabeza negra, dorso gris pizarra y pecho blanco limpio. La cola, negra, termina en una banda blanca que se ve bien en vuelo. Tiene una pequeña corona roja escondida que casi nunca muestra.","diet":"Cambia por completo de dieta según la estación: en Norteamérica caza insectos al vuelo y en Suramérica se vuelve frugívoro, comiendo bayas y frutos en bandadas.","habitat":"Cría en campo abierto con árboles dispersos, orillas de ríos y potreros de Norteamérica. Inverna en bordes de selva de la Amazonia occidental. En la Sabana se ve de paso, en lo alto de árboles aislados.","sw":["#1A1C20","#5A6068","#F6F6F3"],"photos":[{"img":"../bogota/fotos/tyrannus.jpg","mini":"../bogota/fotos/mini/tyrannus.jpg","ind":"Pareja en lo alto de un sauce","place":"Humedal de Córdoba, Bogotá"},{"img":"../bogota/fotos/tyrannus2.jpg","mini":"../bogota/fotos/mini/tyrannus2.jpg","ind":"Vigilando desde la copa de un árbol","place":"Humedal de Córdoba, Bogotá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"De paso anda en grupos que se posan en las ramas más altas y expuestas, y salen en vuelos cortos tras insectos o a arrancar frutos. Su llamado es un chirrido eléctrico y seco.","donde":"Copas de árboles aislados y sauces, en septiembre–octubre y marzo–abril. Busca siluetas blancas y negras en las puntas de las ramas.","id":"tyrannus-tyrannus"}],"en":"Eastern Kingbird","enAlt":"Sirirí norteño · Tirano oriental","g":17},{"k":"Myiozetetes similis","common":"Suelda social","alt":"Bichofué chico · Social Flycatcher","sci":"Myiozetetes similis","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Parecida a un bichofué en miniatura: ceja blanca ancha, antifaz gris oscuro, dorso oliva y vientre amarillo. Se distingue del bichofué por el pico corto y fino, y de su pariente la suelda de alas rojizas por los bordes pálidos, no canela, de las plumas del ala.","diet":"Insectos que caza en vuelo desde una percha, y muchos frutos pequeños.","habitat":"Parques, jardines, orillas arborizadas y bordes de manglar.","sw":["#F4F4F0","#555A5E","#7E8048","#F0DC3A"],"photos":[{"img":"../cartagena/fotos/myiozetetes.jpg","mini":"../cartagena/fotos/mini/myiozetetes.jpg","ind":"Sobre una piedra coralina, de perfil","place":"Paseo peatonal de Manga, Cartagena"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Ruidosa y sociable: llama con un «chí-chí» repetido y se junta en parejas o grupos pequeños en las copas.","donde":"Árboles del paseo y muros de piedra junto al agua.","id":"myiozetetes-similis"}],"en":"Social Flycatcher","enAlt":"Suelda social · Bichofué chico","g":17},{"k":"Fluvicola pica","common":"Viudita","alt":"Viudita acuática · Pied Water-Tyrant","sci":"Fluvicola pica","family":"Tyrannidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pequeño atrapamoscas blanco con la nuca, la espalda y las alas negras, como un traje de viuda. Mueve la cola continuamente.","diet":"Insectos pequeños que caza saltando entre la vegetación flotante y las orillas.","habitat":"Orillas de ciénagas, lagunas y canales con plantas acuáticas.","sw":["#F7F7F5","#141414"],"photos":[{"img":"../pijino/fotos/fluvicola.jpg","mini":"../pijino/fotos/mini/fluvicola.jpg","ind":"Adulto, blanco y negro","place":"Ciénaga de Pijiño, Magdalena"}],"where":[{"l":"pijino","nom":"Ciénaga de Pijiño","hab":"Inquieta: salta entre la vegetación flotante y las orillas, abriendo la cola. Anda sola o en pareja.","donde":"Plantas flotantes y orillas con juncos.","id":"fluvicola-pica"}],"en":"Pied Water-Tyrant","enAlt":"Viudita · Viudita acuática","g":17},{"k":"Cyclarhis gujanensis","common":"Verderón cejirrufo","alt":"Vireón cejirrufo · Rufous-browed Peppershrike","sci":"Cyclarhis gujanensis","family":"Vireonidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Cabeza gris con una ceja rojiza muy marcada, dorso verde oliva y pecho amarillo. El pico es grueso, pálido y ganchudo, como el de un alcaudón pequeño.","diet":"Orugas, saltamontes y otros insectos grandes, que sujeta con la pata mientras los despedaza; algunos frutos.","habitat":"Bosque seco, bordes, cercas vivas y jardines arbolados.","sw":["#9AA0A6","#B5552A","#8FA03A","#E3D03A"],"photos":[{"img":"../barichara/fotos/cyclarhis.jpg","mini":"../barichara/fotos/mini/cyclarhis.jpg","ind":"Adulto junto a un tronco","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Se oye mucho más de lo que se ve: repite una misma frase silbada decenas de veces y luego cambia a otra. Se mueve despacio entre el follaje.","donde":"Copas medias de árboles en cercas y bordes; búsquelo por el canto.","id":"cyclarhis-gujanensis"}],"en":"Rufous-browed Peppershrike","enAlt":"Verderón cejirrufo · Vireón cejirrufo","g":18},{"k":"Pygochelidon cyanoleuca","common":"Golondrina blanquiazul","alt":"Blue-and-white Swallow","sci":"Pygochelidon cyanoleuca","family":"Hirundinidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Golondrina pequeña, azul oscuro brillante por encima y clara por debajo. Los jóvenes son más opacos y tienen el vientre pardusco. Pasa el día en vuelo sobre potreros y casas y se reúne a descansar en cables y muros.","diet":"Insectos pequeños capturados en vuelo.","habitat":"Áreas abiertas, pueblos y ciudades. Anida en huecos de edificios, aleros y taludes.","sw":["#1F4E7A","#2E6E9E","#EDE6DA"],"photos":[{"img":"../bogota/fotos/pygochelidon.jpg","mini":"../bogota/fotos/mini/pygochelidon.jpg","ind":"Grupo posado en un muro","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/pygoJuv.jpg","mini":"../bogota/fotos/mini/pygoJuv.jpg","ind":"Juvenil recién salido del nido","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Gregaria. Pasa casi todo el día en vuelo, cazando a baja altura, y se reúne a descansar en grupo en cables, muros y tejados.","donde":"Volando sobre potreros y edificaciones; posadas en muros y cables al final de la tarde. Todo el año.","id":"pygochelidon-cyanoleuca"}],"en":"Blue-and-white Swallow","enAlt":"Golondrina blanquiazul","g":19},{"k":"Troglodytes aedon","common":"Cucarachero","alt":"Cucarachero común · House Wren","sci":"Troglodytes aedon","family":"Troglodytidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pájaro pequeño y pardo con finas barras oscuras en alas y cola, que suele llevar levantada. Su canto es un trino largo, rápido y burbujeante, sorprendentemente fuerte para su tamaño.","diet":"Insectos, arañas, cucarachas y larvas que busca entre hojarasca, rendijas y arbustos.","habitat":"Jardines, setos, potreros con arbustos y casas. Anida en huecos de muros, tejados y cajas nido.","sw":["#7A6650","#D9C9AE","#3E3428"],"photos":[{"img":"../bogota/fotos/troglodytes.jpg","mini":"../bogota/fotos/mini/troglodytes.jpg","ind":"Buscando insectos bajo el seto","place":"Hacienda San Simón, Guaymaral"},{"img":"../barichara/fotos/troglodytes.jpg","mini":"../barichara/fotos/mini/troglodytes.jpg","ind":"Con la cola levantada","place":"Barichara, Santander"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Inquieto y curioso: salta entre las ramas bajas con la cola levantada y regaña con un «chet» seco a quien se acerque. Canta todo el año.","donde":"Base de setos, jardineras, aleros y montones de leña. Todo el año.","id":"troglodytes-aedon"},{"l":"barichara","nom":"Barichara","hab":"Inquieto y curioso: salta entre las ramas bajas con la cola levantada y regaña con un «chet» seco a quien se acerque. Canta todo el año.","donde":"Base de setos, jardineras, aleros y muros de piedra.","id":"troglodytes-aedon"}],"en":"House Wren","enAlt":"Cucarachero · Cucarachero común","g":20},{"k":"Campylorhynchus griseus","common":"Cucarachero chupahuevo","alt":"Cucarachero bicolor · Bicolored Wren","sci":"Campylorhynchus griseus","family":"Troglodytidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El cucarachero más grande de Colombia: dorso pardo rojizo, partes inferiores blancas y una ceja blanca sobre una línea oscura que cruza el ojo. Su nombre local viene de que a veces se come huevos de otras aves.","diet":"Insectos, arañas, lagartijas pequeñas y, a veces, huevos.","habitat":"Zonas secas y abiertas con árboles, cactus, cercas y pueblos. Construye nidos voluminosos de pasto con entrada lateral.","sw":["#7A4A2E","#F4F1EA","#2B2420"],"photos":[{"img":"../barichara/fotos/campylorhynchus.jpg","mini":"../barichara/fotos/mini/campylorhynchus.jpg","ind":"Trepando un tronco con bromelias","place":"Barichara, Santander"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Ruidoso y sociable: vive en grupos familiares que cantan a dúo y defienden el territorio. Trepa troncos y revisa bromelias y huecos.","donde":"Árboles con bromelias, techos y cercas del pueblo.","id":"campylorhynchus-griseus"}],"en":"Bicolored Wren","enAlt":"Cucarachero chupahuevo · Cucarachero bicolor","g":20},{"k":"Mimus gilvus","common":"Sinsonte tropical","alt":"Sinsonte común · Tropical Mockingbird","sci":"Mimus gilvus","family":"Mimidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Gris claro por encima y blancuzco por debajo, con antifaz oscuro y cola larga de puntas blancas que abre al posarse. Canta desde perchas altas, con frases variadas y repetidas.","diet":"Omnívoro: insectos, arañas, frutos y semillas. Busca alimento en el suelo y en arbustos.","habitat":"Áreas abiertas, potreros con árboles, cercas vivas, jardines y zonas urbanas, del nivel del mar hasta la Sabana.","sw":["#A4A49E","#ECEAE4","#2A2A2A"],"photos":[{"img":"../bogota/fotos/gilvus3.jpg","mini":"../bogota/fotos/mini/gilvus3.jpg","ind":"Adulto sobre el muro de ladrillo","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/gilvus.jpg","mini":"../bogota/fotos/mini/gilvus.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/gilvus2.jpg","mini":"../bogota/fotos/mini/gilvus2.jpg","ind":"Con un fruto en el pico, sobre el tejado","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/gilvus4.jpg","mini":"../bogota/fotos/mini/gilvus4.jpg","ind":"Adulto entre las hojas, con el antifaz oscuro y la cola larga","place":"Hacienda San Simón, Guaymaral"},{"img":"../barichara/fotos/mimus.jpg","mini":"../barichara/fotos/mini/mimus.jpg","ind":"Cantando desde una rama","place":"Barichara, Santander"},{"img":"../barichara/fotos/mimus2.jpg","mini":"../barichara/fotos/mini/mimus2.jpg","ind":"Pareja en un árbol cubierto de líquenes y barbas de viejo","place":"Barichara, Santander"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Territorial y vocal. Canta desde lo más alto y abre las alas de golpe, mostrando el blanco, para espantar insectos o rivales.","donde":"Postes, cercas y copas de arbustos en zonas abiertas. Todo el año.","id":"mimus-gilvus"},{"l":"barichara","nom":"Barichara","hab":"Territorial y vocal. Canta desde lo más alto y abre las alas de golpe, mostrando el blanco, para espantar insectos o rivales.","donde":"Copas de árboles, postes y techos en zonas abiertas.","id":"mimus-gilvus"}],"en":"Tropical Mockingbird","enAlt":"Sinsonte tropical · Sinsonte común","g":21},{"k":"Turdus ignobilis","common":"Mirla embarradora","alt":"Mirla ollera · Black-billed Thrush","sci":"Turdus ignobilis","family":"Turdidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Mirla parda oliva, más pequeña y oscura que la mirla parda, con el pico negro y la garganta blancuzca finamente rayada. Su nombre local viene del barro con el que arma el nido.","diet":"Lombrices, insectos y frutos, entre ellos papaya y banano.","habitat":"Jardines, cafetales, potreros con árboles y bordes de bosque de tierras medias.","sw":["#6A5E4A","#A89A84","#151515"],"photos":[{"img":"../cafetera/fotos/ignobilis.jpg","mini":"../cafetera/fotos/mini/ignobilis.jpg","ind":"Posada en un palo de papaya","place":"Zona Cafetera"},{"img":"../cafetera/fotos/ignobilis2.jpg","mini":"../cafetera/fotos/mini/ignobilis2.jpg","ind":"En el comedero de guadua, junto al banano","place":"Zona Cafetera"},{"img":"../cafetera/fotos/ignobilis3.jpg","mini":"../cafetera/fotos/mini/ignobilis3.jpg","ind":"En las hojas de un palo de papaya","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Camina por el suelo picando lombrices y sube a los frutales; canta un trino variado al amanecer.","donde":"Papayos, comederos y prados.","id":"turdus-ignobilis"}],"en":"Black-billed Thrush","enAlt":"Mirla embarradora · Mirla ollera","g":22},{"k":"Turdus grayi","common":"Mirla parda","alt":"Zorzal pardo · Clay-colored Thrush","sci":"Turdus grayi","family":"Turdidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Zorzal pardo claro, sin marcas llamativas, con el pico amarillo verdoso y la garganta finamente rayada. Mucho más pálido y pequeño que la mirla patinaranja.","diet":"Lombrices e insectos que busca en el suelo; frutos y bayas en los árboles.","habitat":"Jardines, parques, cafetales y bordes de bosque en tierras bajas y medias. En la Sabana es menos común que la mirla patinaranja.","sw":["#8A7A5C","#C2AE88","#C9B23A"],"photos":[{"img":"../bogota/fotos/grayi.jpg","mini":"../bogota/fotos/mini/grayi.jpg","ind":"Adulto en la copa de un árbol","place":"Hacienda San Simón, Guaymaral"},{"img":"../cafetera/fotos/turdus.jpg","mini":"../cafetera/fotos/mini/turdus.jpg","ind":"Juvenil, con el pecho moteado","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Tranquila y discreta. Busca alimento en el suelo bajo los árboles y sube al dosel a comer frutos. Su canto es un silbido largo y melodioso, sobre todo al comenzar las lluvias.","donde":"Copas de árboles frondosos y el suelo bajo ellos, en la mañana. Todo el año.","id":"turdus-grayi"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Busca alimento en el suelo bajo los árboles; canta largo al inicio de las lluvias.","donde":"Jardines y comederos.","id":"turdus-grayi"}],"en":"Clay-colored Thrush","enAlt":"Mirla parda · Zorzal pardo","g":22},{"k":"Turdus fuscater","common":"Mirla patinaranja","alt":"Mirla grande · Great Thrush","sci":"Turdus fuscater","family":"Turdidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El zorzal más grande del mundo. Pardo oscuro, con pico, patas y anillo ocular anaranjados. Camina dando saltos por el césped y se detiene a escuchar antes de picar.","diet":"Lombrices, insectos, frutos y semillas; muy oportunista.","habitat":"Jardines, potreros, parques y bordes de bosque andino, entre unos 1.800 y 4.000 m. Es de las aves más comunes de Bogotá.","sw":["#3A3530","#E8792A","#F2A93B"],"photos":[{"img":"../bogota/fotos/turdus.jpg","mini":"../bogota/fotos/mini/turdus.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Camina y salta por el césped, se detiene, inclina la cabeza para escuchar y clava el pico para sacar una lombriz. Canta al amanecer, a veces antes de que salga el sol.","donde":"Prados y jardines, sobre todo después de la lluvia o del riego. Todo el año.","id":"turdus-fuscater"}],"en":"Great Thrush","enAlt":"Mirla patinaranja · Mirla grande","g":22},{"k":"Euphonia laniirostris","common":"Eufonia piquigruesa","alt":"Thick-billed Euphonia","sci":"Euphonia laniirostris","family":"Fringillidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Pequeña y compacta: azul oscuro brillante por encima y amarillo intenso por debajo, con la frente amarilla.","diet":"Frutos pequeños, sobre todo de muérdagos, cuyas semillas ayuda a dispersar; banano en comederos.","habitat":"Bordes de bosque, cafetales y jardines.","sw":["#1E2A5A","#F2C21A"],"photos":[{"img":"../cafetera/fotos/euphonia.jpg","mini":"../cafetera/fotos/mini/euphonia.jpg","ind":"Macho en el comedero","place":"Zona Cafetera"},{"img":"../cafetera/fotos/euphonia2.jpg","mini":"../cafetera/fotos/mini/euphonia2.jpg","ind":"Macho comiendo banano","place":"Zona Cafetera"},{"img":"../cafetera/fotos/euphonia3.jpg","mini":"../cafetera/fotos/mini/euphonia3.jpg","ind":"Macho joven en vuelo, aún verde oliva","place":"Zona Cafetera"},{"img":"../cafetera/fotos/euphonia4.jpg","mini":"../cafetera/fotos/mini/euphonia4.jpg","ind":"Macho de perfil, con la garganta amarilla","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas que recorren las copas buscando frutos de muérdago.","donde":"Comederos y árboles con muérdago.","id":"euphonia-laniirostris"}],"en":"Thick-billed Euphonia","enAlt":"Eufonia piquigruesa","g":23},{"k":"Spinus psaltria","common":"Jilguero","alt":"Lesser Goldfinch o Andean Siskin","sci":"Spinus psaltria / S. spinescens","family":"Fringillidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"baja","desc":"Pinzón pequeño y amarillo con corona negra en el macho. Vuela en grupos con trayectoria ondulante y se posa en lo alto de ramas secas.","diet":"Semillas pequeñas, especialmente de hierbas y de la familia del diente de león.","habitat":"Áreas abiertas con arbustos, bordes, jardines y potreros de la Sabana.","sw":["#E2C318","#4C5A1E","#141414"],"photos":[{"img":"../bogota/fotos/spinus.jpg","mini":"../bogota/fotos/mini/spinus.jpg","ind":"Macho, a contraluz","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Anda en grupos pequeños y parlanchines, con vuelo ondulante. Se cuelga de las plantas para sacarles las semillas.","donde":"Plantas en semilla (dientes de león, cardos) y copas peladas de árboles. Todo el año.","id":"spinus"}],"en":"Lesser Goldfinch or Andean Siskin","enAlt":"Jilguero","g":23},{"k":"Zonotrichia capensis","common":"Copetón","alt":"Gorrión copetón · Rufous-collared Sparrow","sci":"Zonotrichia capensis","family":"Passerellidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El ave más familiar de la Sabana. Cabeza gris con rayas negras y un pequeño copete, collar rufo en la nuca y mancha negra a los lados del pecho. Su silbido claro se oye desde antes del amanecer. Los jóvenes son pardos y rayados, sin el collar rufo.","diet":"Semillas de pastos y hierbas; insectos, sobre todo cuando alimenta a los pichones.","habitat":"Potreros, jardines, cultivos, parques y bordes de bosque, desde tierras medias hasta el páramo.","sw":["#B5652F","#7A746B","#2B2723","#8A6A48"],"photos":[{"img":"../bogota/fotos/zonotrichia.jpg","mini":"../bogota/fotos/mini/zonotrichia.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/zonotrichiaJuv.jpg","mini":"../bogota/fotos/mini/zonotrichiaJuv.jpg","ind":"Juvenil rayado, sin collar todavía, en un bebedero","place":"Cerro de Monserrate, Bogotá"},{"img":"../cafetera/fotos/zonotrichia.jpg","mini":"../cafetera/fotos/mini/zonotrichia.jpg","ind":"Adulto sobre una rama con barba de viejo","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Vive en parejas que defienden su territorio todo el año. Se alimenta en el suelo dando saltitos y alza el copete cuando está alerta. Su canto se oye a cualquier hora, incluso de noche.","donde":"En el césped, bordes de caminos y cercas, prácticamente en cualquier rincón abierto. Todo el año.","id":"zonotrichia-capensis"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas que defienden su territorio todo el año; canta a cualquier hora.","donde":"Potreros, caminos y cercas.","id":"zonotrichia-capensis"}],"en":"Rufous-collared Sparrow","enAlt":"Copetón · Gorrión copetón","g":24},{"k":"Atlapetes pallidinucha","common":"Gorrión montés de nuca pálida","alt":"Pale-naped Brushfinch","sci":"Atlapetes pallidinucha","family":"Passerellidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Cara negra, frente canela anaranjada que se aclara a blanco en la nuca, dorso gris oscuro y vientre amarillo oliva.","diet":"Insectos, semillas y frutos que busca entre la hojarasca y el musgo.","habitat":"Sotobosque y bordes de bosque altoandino, entre unos 2.500 y 3.600 m.","sw":["#121212","#D88A3A","#F4F0E4","#B8B84A"],"photos":[{"img":"../cafetera/fotos/atlapetes.jpg","mini":"../cafetera/fotos/mini/atlapetes.jpg","ind":"Buscando comida en el musgo","place":"Zona Cafetera"},{"img":"../cafetera/fotos/atlapetes2.jpg","mini":"../cafetera/fotos/mini/atlapetes2.jpg","ind":"De frente entre ramas con líquenes, con la frente amarilla","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Se mueve en parejas por el suelo y el sotobosque, escarbando la hojarasca.","donde":"Sotobosque húmedo con musgo en bosques altos.","id":"atlapetes-pallidinucha"}],"en":"Pale-naped Brushfinch","enAlt":"Gorrión montés de nuca pálida","g":24},{"k":"Quiscalus mexicanus","common":"María mulata","alt":"Zanate mayor · Great-tailed Grackle","sci":"Quiscalus mexicanus","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es negro con brillo violeta, ojo amarillo pálido y una cola muy larga que pliega en forma de quilla de barco. La hembra es parda y más pequeña. Es el ave emblema de Cartagena, inmortalizada en las esculturas de Enrique Grau.","diet":"Omnívora: insectos, frutos, semillas, cangrejos, huevos y restos de comida.","habitat":"Costas, pueblos, potreros, manglares y orillas de ciénagas.","sw":["#16121E","#4A2E6A","#E8E2A0"],"photos":[{"img":"../cartagena/fotos/quiscalus2.jpg","mini":"../cartagena/fotos/mini/quiscalus2.jpg","ind":"Macho con la cola larga desplegada","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalus3.jpg","mini":"../cartagena/fotos/mini/quiscalus3.jpg","ind":"Hembra, parda y de ojo claro","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalusF.jpg","mini":"../cartagena/fotos/mini/quiscalusF.jpg","ind":"Hembra entre ramas con flores","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalusMG3.jpg","mini":"../cartagena/fotos/mini/quiscalusMG3.jpg","ind":"Dos jóvenes en un flamboyán; uno pide comida con el pico abierto","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalusMG.jpg","mini":"../cartagena/fotos/mini/quiscalusMG.jpg","ind":"Hembra de ojo claro en las hojas de un flamboyán","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalusMG2.jpg","mini":"../cartagena/fotos/mini/quiscalusMG2.jpg","ind":"Joven con el pecho canela","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../cartagena/fotos/quiscalus.jpg","mini":"../cartagena/fotos/mini/quiscalus.jpg","ind":"Macho cantando desde un tronco","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/quiscalusIR.jpg","mini":"../cartagena/fotos/mini/quiscalusIR.jpg","ind":"Macho a contraluz en un árbol de playa","place":"Islas del Rosario y Barú"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Muy sociable y ruidosa: los machos se pavonean con el pico hacia arriba y las plumas erizadas, y lanzan silbidos y chasquidos.","donde":"Potreros, orillas de caños y cualquier pueblo de la región.","id":"quiscalus-mexicanus"}],"en":"Great-tailed Grackle","enAlt":"María mulata · Zanate mayor","g":25},{"k":"Psarocolius decumanus","common":"Mochilero","alt":"Oropéndola crestada · Crested Oropendola","sci":"Psarocolius decumanus","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Negro con la rabadilla castaña, ojos azul claro, pico marfil y cola amarilla brillante. El macho, mucho más grande que la hembra, se inclina hacia adelante al cantar, con un sonido líquido y gorgoteante.","diet":"Frutos, néctar, insectos y ocasionalmente huevos y pichones.","habitat":"Bordes de bosque, potreros con árboles altos y orillas de ríos.","sw":["#121212","#F2C21A","#E8E2C8","#8ACAE8"],"photos":[{"img":"../boyaca/fotos/decumanus.jpg","mini":"../boyaca/fotos/mini/decumanus.jpg","ind":"Macho, con el ojo azul y la cola amarilla","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"En grupos que visitan los árboles frutales; los machos hacen reverencias al cantar junto a la colonia.","donde":"Árboles altos en bordes de potrero y quebradas.","id":"psarocolius-decumanus"}],"en":"Crested Oropendola","enAlt":"Mochilero · Oropéndola crestada","g":25},{"k":"Psarocolius angustifrons","common":"Mochilero pardo","alt":"Oropéndola dorsirrojiza · Russet-backed Oropendola","sci":"Psarocolius angustifrons","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Grande, pardo castaño con la cabeza oliva, un pico grande y pálido y la cola amarillo intenso que muestra al volar. Teje nidos colgantes en forma de mochila, de hasta un metro de largo, en colonias sobre árboles altos.","diet":"Frutos (papaya, naranjas, guamos), néctar, insectos y pequeños animales.","habitat":"Bordes de bosque, cafetales con sombrío, huertos y árboles aislados en potreros.","sw":["#7A4A2A","#A89A3A","#F2C21A","#E8D8B0"],"photos":[{"img":"../boyaca/fotos/angustifrons.jpg","mini":"../boyaca/fotos/mini/angustifrons.jpg","ind":"Entre las ramas de un naranjo","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/angustifrons2.jpg","mini":"../boyaca/fotos/mini/angustifrons2.jpg","ind":"Con la cola levantada","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/angustifrons3.jpg","mini":"../boyaca/fotos/mini/angustifrons3.jpg","ind":"Comiendo papaya madura","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"Vive en colonias ruidosas: los machos cantan inclinándose hacia adelante y abriendo las alas. Vuela de árbol en árbol con aleteo pesado.","donde":"Naranjos, papayos y árboles altos con sus nidos colgantes.","id":"psarocolius-angustifrons"}],"en":"Russet-backed Oropendola","enAlt":"Mochilero pardo · Oropéndola dorsirrojiza","g":25},{"k":"Chrysomus icterocephalus","common":"Monjita","alt":"Turpial de agua · Yellow-hooded Blackbird","sci":"Chrysomus icterocephalus","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es negro brillante con una capucha amarillo intenso y un pequeño antifaz negro entre el pico y el ojo. La hembra es parda oliva con la garganta y la ceja amarillentas.","diet":"Insectos y semillas que busca entre juncos, eneas y pastos altos.","habitat":"Ciénagas, juncales, arrozales y canales. Anida en colonias sobre la vegetación del agua.","sw":["#F2C21A","#111214"],"photos":[{"img":"../cartagena/fotos/chrysomus.jpg","mini":"../cartagena/fotos/mini/chrysomus.jpg","ind":"Macho con la capucha amarilla","place":"Arjona, Bolívar"},{"img":"../cartagena/fotos/chrysomus2.jpg","mini":"../cartagena/fotos/mini/chrysomus2.jpg","ind":"Macho entre el follaje","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"Vive en colonias ruidosas. Los machos cantan con un chirrido metálico desde lo alto de los juncos y de los árboles junto al agua.","donde":"Juncales y árboles a la orilla de la ciénaga.","id":"chrysomus-icterocephalus"}],"en":"Yellow-hooded Blackbird","enAlt":"Monjita · Turpial de agua","g":25},{"k":"Leistes militaris","common":"Soldadito","alt":"Pecho colorado · Red-breasted Meadowlark","sci":"Leistes militaris","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es negro con la garganta y el pecho rojo escarlata, como un uniforme militar. La hembra es parda y rayada, con un tinte rosado en el pecho.","diet":"Insectos y semillas que busca en el suelo, entre el pasto.","habitat":"Potreros húmedos, pastizales y arrozales.","sw":["#141414","#C8282A"],"photos":[{"img":"../cartagena/fotos/leistes.jpg","mini":"../cartagena/fotos/mini/leistes.jpg","ind":"Macho posado sobre la maleza","place":"Arjona, Bolívar"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"El macho canta desde la punta de una mata y hace un vuelo corto de exhibición mostrando el pecho rojo; luego se deja caer entre el pasto.","donde":"Pastizales húmedos y potreros con pasto alto.","id":"leistes-militaris"}],"en":"Red-breasted Meadowlark","enAlt":"Soldadito · Pecho colorado","g":25},{"k":"Icterus chrysater","common":"Toche","alt":"Turpial montañero · Yellow-backed Oriole","sci":"Icterus chrysater","family":"Icteridae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Amarillo intenso con la cara, la garganta, las alas y la cola negras. A diferencia de otros turpiales, la espalda también es amarilla. Canta un silbido aflautado y variado.","diet":"Insectos, frutos y néctar. Frecuenta árboles frutales como el durazno de la foto.","habitat":"Bordes de bosque, cafetales, jardines y huertos. Teje nidos colgantes en forma de bolsa.","sw":["#F2B400","#E08A00","#151515"],"photos":[{"img":"../bogota/fotos/icterus.jpg","mini":"../bogota/fotos/mini/icterus.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../cafetera/fotos/icterus.jpg","mini":"../cafetera/fotos/mini/icterus.jpg","ind":"Posado en una hoja de plátano","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Anda en parejas, recorriendo el follaje con calma. Su canto es un silbido aflautado y melodioso. Teje nidos colgantes en forma de bolsa.","donde":"Árboles frutales como el durazno, árboles en flor y cercas vivas. Todo el año.","id":"icterus-chrysater"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas, recorre el follaje con calma y teje nidos colgantes.","donde":"Plataneras, frutales y bordes.","id":"icterus-chrysater"}],"en":"Yellow-backed Oriole","enAlt":"Toche · Turpial montañero","g":25},{"k":"Setophaga petechia","common":"Reinita amarilla","alt":"Chipe amarillo · Yellow Warbler","sci":"Setophaga petechia","family":"Parulidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Pequeña reinita casi toda amarilla, con el ojo oscuro destacado en una cara lisa. El macho lleva finas rayas castañas en el pecho. Se mueve sin parar entre las ramas.","diet":"Insectos y arañas que toma de hojas y ramas; orugas en buena proporción.","habitat":"Cría en matorrales húmedos, sauces y bordes de agua desde Alaska hasta México. Inverna en jardines, bordes y cultivos arbolados de América Central y el norte de Suramérica.","sw":["#E8D33A","#B5AC3A","#A5532B"],"photos":[{"img":"../bogota/fotos/petechia.jpg","mini":"../bogota/fotos/mini/petechia.jpg","ind":"Macho, con rayas rojizas en el pecho","place":"Lugar por confirmar"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Muy activa: revolotea sin parar entre las hojas y se cuelga para alcanzar insectos. Defiende un pequeño territorio incluso durante la invernada.","donde":"Arbustos y árboles bajos cerca del agua, sauces y setos. Mañanas, de septiembre a abril.","id":"setophaga-petechia"}],"en":"Yellow Warbler","enAlt":"Reinita amarilla · Chipe amarillo","g":26},{"k":"Piranga olivacea","common":"Piranga escarlata","alt":"Tangara escarlata · Scarlet Tanager","sci":"Piranga olivacea","family":"Cardinalidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"Pariente de los cardenales, no de las tangaras. El macho reproductor es rojo escarlata con alas y cola negras: verlo así en la Sabana es un regalo, porque suele mudar a ese plumaje justo antes de volver al norte. El resto del año, y en hembras y jóvenes, es verde oliva y amarillo, con las alas oscuras que lo separan de la piranga roja hembra.","diet":"Insectos en el dosel (avispas, abejas, escarabajos, orugas). En invernada suma frutos, por eso llega a comederos con papaya y banano.","habitat":"Cría en bosques caducifolios maduros del este de Norteamérica. Inverna en bosques andinos, bordes y jardines arbolados, entre unos 300 y 2.800 m.","sw":["#E2321F","#B9B23E","#E2D96A","#2B2B30"],"photos":[{"img":"../bogota/fotos/olivaceaM.jpg","mini":"../bogota/fotos/mini/olivaceaM.jpg","ind":"Macho en plumaje reproductivo","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/olivaceaM2.jpg","mini":"../bogota/fotos/mini/olivaceaM2.jpg","ind":"Macho de frente, en lo alto del árbol","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/olivacea.jpg","mini":"../bogota/fotos/mini/olivacea.jpg","ind":"Hembra o inmaduro, plumaje no reproductivo","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/olivaceaF2.jpg","mini":"../bogota/fotos/mini/olivaceaF2.jpg","ind":"Hembra discutiendo con un azulejo por el puesto en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/olivaceaF3.jpg","mini":"../bogota/fotos/mini/olivaceaF3.jpg","ind":"Hembra junto a un azulejo, con el ala negruzca y el cuerpo verde oliva","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Discreta y lenta: recorre el dosel revisando hojas con calma y puede pasar largo rato quieta. A menudo se une a bandadas mixtas de tangaras y reinitas.","donde":"En el comedero de frutas, sobre todo en la tarde, y en las copas de los árboles de los bordes. De octubre a abril.","id":"piranga-olivacea"}],"en":"Scarlet Tanager","enAlt":"Piranga escarlata · Tangara escarlata","g":27},{"k":"Piranga rubra","common":"Piranga roja","alt":"Tangara veranera · Summer Tanager","sci":"Piranga rubra","family":"Cardinalidae","iucn":"LC","mig":true,"dom":false,"feral":false,"conf":"alta","desc":"El único pájaro de Norteamérica completamente rojo. El macho conserva el rojo todo el año. La hembra y los jóvenes son amarillo anaranjado, con el pico grueso y claro que comparten con el macho.","diet":"Especialista en abejas y avispas: las caza al vuelo y les quita el aguijón golpeándolas contra una rama. Complementa con frutos e insectos.","habitat":"Cría en bosques abiertos de pino y roble del sur de EE. UU. y norte de México. Inverna en bordes de bosque, cafetales, parques y jardines hasta unos 3.000 m.","sw":["#D12E1F","#E9822F","#C9B48A"],"photos":[{"img":"../bogota/fotos/rubra.jpg","mini":"../bogota/fotos/mini/rubra.jpg","ind":"Macho adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraF.jpg","mini":"../bogota/fotos/mini/rubraF.jpg","ind":"Hembra o macho joven, tonos anaranjados","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraF3.jpg","mini":"../bogota/fotos/mini/rubraF3.jpg","ind":"Hembra, amarillo mostaza","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraF2.jpg","mini":"../bogota/fotos/mini/rubraF2.jpg","ind":"Hembra en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraFSS.jpg","mini":"../bogota/fotos/mini/rubraFSS.jpg","ind":"Hembra o macho joven en el comedero, con papaya","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraSS3.jpg","mini":"../bogota/fotos/mini/rubraSS3.jpg","ind":"Macho joven mudando a rojo, comiendo papaya en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/rubraFSS2.jpg","mini":"../bogota/fotos/mini/rubraFSS2.jpg","ind":"Hembra con banano en el pico","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Tranquila y paciente: se queda inmóvil largos ratos en el dosel antes de moverse. Saquea avisperos y panales para comerse las larvas.","donde":"Comederos de papaya y banano, y árboles altos del jardín. De octubre a abril.","id":"piranga-rubra"}],"en":"Summer Tanager","enAlt":"Piranga roja · Tangara veranera","g":27},{"k":"Ramphocelus dimidiatus","common":"Asoma terciopelo","alt":"Sangre de toro · Crimson-backed Tanager","sci":"Ramphocelus dimidiatus","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es rojo sangre oscuro, con alas y cola negras y una base del pico plateada brillante. La hembra es parda rojiza, más apagada. Anda en grupos pequeños y ruidosos.","diet":"Frutos, banano y papaya en comederos, e insectos.","habitat":"Bordes de bosque, cafetales, rastrojos y jardines de tierras bajas y medias.","sw":["#A0141E","#141414","#E8ECEE"],"photos":[{"img":"../cafetera/fotos/dimidiatus2.jpg","mini":"../cafetera/fotos/mini/dimidiatus2.jpg","ind":"Macho en el comedero","place":"Zona Cafetera"},{"img":"../cafetera/fotos/dimidiatus.jpg","mini":"../cafetera/fotos/mini/dimidiatus.jpg","ind":"Macho entre las heliconias","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"En grupos pequeños que se mueven por la vegetación baja y llegan al comedero con un llamado metálico.","donde":"Comederos y matorrales con heliconias.","id":"ramphocelus-dimidiatus"}],"en":"Crimson-backed Tanager","enAlt":"Asoma terciopelo · Sangre de toro","g":28},{"k":"Thraupis episcopus","common":"Azulejo común","alt":"Tangara azuleja · Blue-gray Tanager","sci":"Thraupis episcopus","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Gris azulado pálido con hombros azul celeste brillante. Inquieto y ruidoso, anda en parejas y llega a los comederos junto con el azulejo palmero.","diet":"Frutos (banano, papaya, guayaba), néctar e insectos.","habitat":"Bordes, jardines, parques, cultivos y ciudades. Muy adaptado a ambientes humanos.","sw":["#A9C4CC","#4FA3C4","#6E8E99"],"photos":[{"img":"../bogota/fotos/episcopusSS.jpg","mini":"../bogota/fotos/mini/episcopusSS.jpg","ind":"En el comedero de banano","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/episcopus2.jpg","mini":"../bogota/fotos/mini/episcopus2.jpg","ind":"Entre el follaje, con los hombros azules a la vista","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/episcopusSS2.jpg","mini":"../bogota/fotos/mini/episcopusSS2.jpg","ind":"Con un trozo de fruta en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../barichara/fotos/episcopus.jpg","mini":"../barichara/fotos/mini/episcopus.jpg","ind":"En un árbol de flor de fuego","place":"Barichara, Santander"},{"img":"../cafetera/fotos/episcopus2.jpg","mini":"../cafetera/fotos/mini/episcopus2.jpg","ind":"En un palo de papaya","place":"Zona Cafetera"},{"img":"../cafetera/fotos/episcopus.jpg","mini":"../cafetera/fotos/mini/episcopus.jpg","ind":"En el comedero de banano","place":"Zona Cafetera"},{"img":"../cafetera/fotos/episcopus3.jpg","mini":"../cafetera/fotos/mini/episcopus3.jpg","ind":"En vuelo, con las alas celestes abiertas","place":"Zona Cafetera"},{"img":"../boyaca/fotos/episcopus.jpg","mini":"../boyaca/fotos/mini/episcopus.jpg","ind":"Posado sobre flores rojas","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Inquieto y ruidoso. Anda en parejas o grupos pequeños y suele imponerse sobre otras aves en el comedero.","donde":"Comedero de frutas, palmas y árboles del jardín. Todo el año.","id":"thraupis-episcopus"},{"l":"barichara","nom":"Barichara","hab":"Inquieto y ruidoso. Anda en parejas o grupos pequeños y suele imponerse sobre otras aves en el comedero.","donde":"Árboles floridos, frutales y comederos de fruta.","id":"thraupis-episcopus"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Inquieto y ruidoso; llega en pareja al comedero.","donde":"Comederos de fruta y árboles del jardín.","id":"thraupis-episcopus"},{"l":"boyaca","nom":"Boyacá","hab":"Inquieto y ruidoso; anda en parejas.","donde":"Arbustos con flor y frutales.","id":"thraupis-episcopus"}],"en":"Blue-gray Tanager","enAlt":"Azulejo común · Tangara azuleja","g":28},{"k":"Thraupis palmarum","common":"Azulejo palmero","alt":"Tangara palmera · Palm Tanager","sci":"Thraupis palmarum","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Verde oliva grisáceo con brillo amarillento según la luz; la mitad de las alas es negruzca y contrasta con la base clara. Anda en parejas o grupos pequeños y es de los primeros en llegar al comedero.","diet":"Frutos (banano, papaya, moras), insectos que busca bajo las hojas, y néctar.","habitat":"Bordes de bosque, jardines, cultivos y sobre todo palmas, donde también anida. Llega hasta unos 2.600 m.","sw":["#A9A86A","#7E8F6B","#2C2C2C"],"photos":[{"img":"../bogota/fotos/palmarum.jpg","mini":"../bogota/fotos/mini/palmarum.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/palmarum2.jpg","mini":"../bogota/fotos/mini/palmarum2.jpg","ind":"Adulto en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/palmarum3.jpg","mini":"../bogota/fotos/mini/palmarum3.jpg","ind":"Pareja compartiendo banano","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/palmarumSS.jpg","mini":"../bogota/fotos/mini/palmarumSS.jpg","ind":"Entre las ramas, con la corona amarillenta","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/palmarumSS2.jpg","mini":"../bogota/fotos/mini/palmarumSS2.jpg","ind":"De frente en el comedero","place":"Hacienda San Simón, Guaymaral"},{"img":"../boyaca/fotos/palmarum.jpg","mini":"../boyaca/fotos/mini/palmarum.jpg","ind":"Comiendo en un arbusto florido","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Acrobático: trepa por las hojas de las palmas y se cuelga boca abajo para revisar el envés en busca de insectos.","donde":"Palmas y comedero de frutas. Todo el año.","id":"thraupis-palmarum"},{"l":"boyaca","nom":"Boyacá","hab":"Acrobático: se cuelga boca abajo para revisar hojas y flores.","donde":"Arbustos floridos y palmas.","id":"thraupis-palmarum"}],"en":"Palm Tanager","enAlt":"Azulejo palmero · Tangara palmera","g":28},{"k":"Sicalis flaveola","common":"Canario coronado","alt":"Canario costeño · Saffron Finch","sci":"Sicalis flaveola","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es amarillo intenso con la frente y la corona anaranjadas; la hembra y los jóvenes son más opacos y grisáceos. Anda en grupos que comen en el suelo.","diet":"Semillas de pastos y granos; algunos insectos.","habitat":"Áreas abiertas, patios, parques y pueblos de tierras bajas y medias. Anida en huecos, aleros y estructuras como postes y techos.","sw":["#F2C21A","#F08A1C"],"photos":[{"img":"../cartagena/fotos/sicalisMG.jpg","mini":"../cartagena/fotos/mini/sicalisMG.jpg","ind":"Macho posado en un poste","place":"Paseo peatonal de Manga, Cartagena"},{"img":"../barichara/fotos/sicalis2.jpg","mini":"../barichara/fotos/mini/sicalis2.jpg","ind":"Macho de frente","place":"Barichara, Santander"},{"img":"../barichara/fotos/sicalis.jpg","mini":"../barichara/fotos/mini/sicalis.jpg","ind":"Macho comiendo semillas en el patio","place":"Barichara, Santander"},{"img":"../barichara/fotos/sicalis3.jpg","mini":"../barichara/fotos/mini/sicalis3.jpg","ind":"Macho entre pastos altos","place":"Barichara, Santander"},{"img":"../barichara/fotos/sicalis4.jpg","mini":"../barichara/fotos/mini/sicalis4.jpg","ind":"Hembra o joven entre cañas, contra el cielo","place":"Barichara, Santander"},{"img":"../cafetera/fotos/sicalis.jpg","mini":"../cafetera/fotos/mini/sicalis.jpg","ind":"Macho en una rama","place":"Zona Cafetera"},{"img":"../boyaca/fotos/sicalis.jpg","mini":"../boyaca/fotos/mini/sicalis.jpg","ind":"Pareja en un arbusto","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/sicalis2.jpg","mini":"../boyaca/fotos/mini/sicalis2.jpg","ind":"Dos jóvenes, aún con el dorso rayado","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/sicalisJuv.jpg","mini":"../boyaca/fotos/mini/sicalisJuv.jpg","ind":"Juvenil grisáceo y rayado","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"cartagena","nom":"Cartagena y alrededores","hab":"En grupos que comen en el suelo; el macho canta un trino alegre desde postes y cables.","donde":"Postes, prados y zonas verdes del paseo.","id":"sicalis-flaveola"},{"l":"barichara","nom":"Barichara","hab":"Anda en grupos que comen en el suelo. El macho canta un trino alegre desde techos y cercas.","donde":"Patios con semillas, prados y techos de teja.","id":"sicalis-flaveola"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En grupos que comen en el suelo; el macho canta desde ramas altas.","donde":"Potreros, patios y cercas.","id":"sicalis-flaveola"},{"l":"boyaca","nom":"Boyacá","hab":"En grupos que comen en el suelo; los jóvenes andan con los adultos.","donde":"Potreros, patios y arbustos bajos.","id":"sicalis-flaveola"}],"en":"Saffron Finch","enAlt":"Canario coronado · Canario costeño","g":28},{"k":"Anisognathus igniventris","common":"Clarinero escarlata","alt":"Tangara de montaña ventriescarlata · Scarlet-bellied Mountain Tanager","sci":"Anisognathus igniventris","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Negro azabache con una mancha escarlata detrás del ojo, el vientre rojo encendido y un parche azul celeste en el hombro. De espaldas casi parece todo negro, hasta que gira y aparecen los colores.","diet":"Frutos y bayas de arbustos andinos; también insectos y algo de néctar.","habitat":"Bosque altoandino, subpáramo y bordes con arbustos, entre unos 2.500 y 3.700 m. En la Sabana visita jardines con setos y árboles frutales.","sw":["#121417","#E2321F","#4E8FD6"],"photos":[{"img":"../bogota/fotos/anisognathus.jpg","mini":"../bogota/fotos/mini/anisognathus.jpg","ind":"Adulto","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/anisognathus2.jpg","mini":"../bogota/fotos/mini/anisognathus2.jpg","ind":"De espaldas, con el hombro azul a la vista","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/anisognathusM.jpg","mini":"../bogota/fotos/mini/anisognathusM.jpg","ind":"Entre moras silvestres y retamo","place":"Cerro de Monserrate, Bogotá"},{"img":"../cafetera/fotos/anisognathus.jpg","mini":"../cafetera/fotos/mini/anisognathus.jpg","ind":"Adulto entre ramas","place":"Zona Cafetera"},{"img":"../cafetera/fotos/anisognathus2.jpg","mini":"../cafetera/fotos/mini/anisognathus2.jpg","ind":"Entre ramas con musgo: hombro azul y media luna roja en el cuello","place":"Zona Cafetera"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Anda en parejas o grupos ruidosos que recorren los arbustos en busca de frutos. Su canto es un repique metálico y desordenado, como un clarinete.","donde":"Setos y árboles frutales del jardín; más fácil en la mañana. Todo el año.","id":"anisognathus-igniventris"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas o grupos ruidosos que recorren los arbustos; canta un repique metálico.","donde":"Bordes de bosque alto y arbustos frutales.","id":"anisognathus-igniventris"}],"en":"Scarlet-bellied Mountain Tanager","enAlt":"Clarinero escarlata · Tangara de montaña ventriescarlata","g":28},{"k":"Sporophila intermedia","common":"Espiguero gris","alt":"Semillero gris · Gray Seedeater","sci":"Sporophila intermedia","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"media","desc":"Pájaro pequeño y gris pizarra, con un pico grueso y corto, amarillento o rosado, y una manchita blanca en el ala. La hembra es parda.","diet":"Semillas de pastos, que arranca de las espigas o recoge del suelo.","habitat":"Pastizales, bordes de camino, cultivos y jardines con pasto alto.","sw":["#6E737A","#E2B860","#F4F4F0"],"photos":[{"img":"../cafetera/fotos/sporophila.jpg","mini":"../cafetera/fotos/mini/sporophila.jpg","ind":"Macho buscando semillas en el suelo","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Anda en parejas o grupos pequeños que comen en el suelo o colgados de las espigas. El macho canta un trino largo y variado desde una percha baja.","donde":"Bordes de potreros y caminos con pasto en semilla.","id":"sporophila-intermedia"}],"en":"Gray Seedeater","enAlt":"Espiguero gris · Semillero gris","g":28},{"k":"Coereba flaveola","common":"Mielero","alt":"Reinita mielera · Bananaquit","sci":"Coereba flaveola","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pájaro pequeño de pico curvo, gris oscuro por encima, con una ceja blanca muy marcada, garganta gris, pecho amarillo y rabadilla amarilla.","diet":"Néctar, que a menudo «roba» perforando la base de las flores; también frutos y pequeños insectos. Le encantan los bebederos con agua azucarada.","habitat":"Jardines, bordes de bosque, cafetales y pueblos.","sw":["#3A3E44","#F4F4F0","#F2D02A"],"photos":[{"img":"../boyaca/fotos/coereba.jpg","mini":"../boyaca/fotos/mini/coereba.jpg","ind":"Buscando néctar en flores blancas","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/coereba2.jpg","mini":"../boyaca/fotos/mini/coereba2.jpg","ind":"De frente, con la ceja blanca","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"boyaca","nom":"Boyacá","hab":"Muy activo, salta entre flores sin parar y canta un chirrido agudo y repetido.","donde":"Flores de arbustos y jardines; bebederos.","id":"coereba-flaveola"}],"en":"Bananaquit","enAlt":"Mielero · Reinita mielera","g":28},{"k":"Diglossa humeralis","common":"Pinchaflor negro","alt":"Carbonero · Black Flowerpiercer","sci":"Diglossa humeralis","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Pájaro negro opaco, con un parche gris azulado en el hombro y el pico curvo terminado en gancho. Ese pico le permite «robar» néctar: perfora la base de la flor sin polinizarla.","diet":"Néctar, que obtiene perforando las flores; insectos pequeños.","habitat":"Bordes de bosque andino, matorrales, jardines y páramo, entre unos 2.500 y 4.000 m.","sw":["#1B1C22","#3A3D4A","#5C6E8A"],"photos":[{"img":"../bogota/fotos/diglossa.jpg","mini":"../bogota/fotos/mini/diglossa.jpg","ind":"Adulto en farolitos (Abutilon)","place":"Hacienda San Simón, Guaymaral"},{"img":"../bogota/fotos/diglossa2.jpg","mini":"../bogota/fotos/mini/diglossa2.jpg","ind":"Entre el follaje del seto","place":"Hacienda San Simón, Guaymaral"}],"where":[{"l":"bogota","nom":"Bogotá","hab":"Activo y solitario; defiende sus arbustos con flores de otros pájaros. Sujeta la flor con el gancho del pico y la perfora por la base para tomar el néctar.","donde":"Farolitos (Abutilon), fucsias y otras flores tubulares del jardín. Todo el año.","id":"diglossa-humeralis"}],"en":"Black Flowerpiercer","enAlt":"Pinchaflor negro · Carbonero","g":28},{"k":"Saltator striatipectus","common":"Saltador rayado","alt":"Papayero · Streaked Saltator","sci":"Saltator striatipectus","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Cabeza gris, ceja blanca corta, dorso verde oliva y pecho blancuzco con rayas oscuras finas. Tiene el pico grueso y oscuro de los saltadores, ideal para frutos y brotes.","diet":"Frutos, flores, brotes tiernos y semillas; algunos insectos. Le gusta la papaya, de ahí el nombre «papayero».","habitat":"Bordes de bosque seco, rastrojos, cercas vivas, huertas y jardines.","sw":["#7D8A7A","#8C9A3A","#E9E6DC"],"photos":[{"img":"../barichara/fotos/saltator.jpg","mini":"../barichara/fotos/mini/saltator.jpg","ind":"En un bebedero de piedra","place":"Barichara, Santander"},{"img":"../barichara/fotos/saltator2.jpg","mini":"../barichara/fotos/mini/saltator2.jpg","ind":"De espaldas, con las alas verde oliva","place":"Barichara, Santander"},{"img":"../cafetera/fotos/saltator.jpg","mini":"../cafetera/fotos/mini/saltator.jpg","ind":"En el comedero de guadua, con comida en el pico","place":"Zona Cafetera"}],"where":[{"l":"barichara","nom":"Barichara","hab":"Anda en parejas entre arbustos y copas bajas. Canta frases cortas y melodiosas desde una percha visible y baja a beber a pocetas y bebederos.","donde":"Bebederos, árboles frutales y cercas vivas.","id":"saltator-striatipectus"},{"l":"cafetera","nom":"Zona Cafetera","hab":"Anda en parejas entre arbustos y copas bajas y baja a los comederos de fruta. Canta frases cortas y melodiosas desde una percha visible.","donde":"Comederos con banano y papaya, cercas vivas y bordes de cafetal.","id":"saltator-striatipectus"}],"en":"Streaked Saltator","enAlt":"Saltador rayado · Papayero","g":28},{"k":"Stilpnia cyanicollis","common":"Tangara cabeciazul","alt":"Blue-necked Tanager","sci":"Stilpnia cyanicollis","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Cuerpo negro, cabeza y cuello azul turquesa brillante y un parche verde dorado en el hombro. De lejos parece negra, hasta que le da la luz.","diet":"Frutos pequeños, como los del yarumo y los melastomatáceos, e insectos que busca en las ramas.","habitat":"Bordes de bosque, cafetales con sombrío, rastrojos altos y jardines, entre unos 600 y 2.200 m.","sw":["#3CB4E0","#141418","#9CC86A"],"photos":[{"img":"../cafetera/fotos/cyanicollis.jpg","mini":"../cafetera/fotos/mini/cyanicollis.jpg","ind":"Adulto frente a una hoja de yarumo","place":"Zona Cafetera"},{"img":"../boyaca/fotos/cyanicollis.jpg","mini":"../boyaca/fotos/mini/cyanicollis.jpg","ind":"Adulto en un arbusto con flores","place":"Valle de Tenza, Boyacá"},{"img":"../boyaca/fotos/cyanicollis2.jpg","mini":"../boyaca/fotos/mini/cyanicollis2.jpg","ind":"De frente, con el antifaz negro","place":"Valle de Tenza, Boyacá"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas o con bandadas mixtas de tangaras que recorren las copas; revisa ramas y hojas por debajo.","donde":"Yarumos y árboles frutales en bordes de cafetal.","id":"stilpnia-cyanicollis"},{"l":"boyaca","nom":"Boyacá","hab":"En parejas o con bandadas mixtas; revisa ramas y frutos con movimientos rápidos.","donde":"Arbustos floridos y frutales en bordes de potrero.","id":"stilpnia-cyanicollis"}],"en":"Blue-necked Tanager","enAlt":"Tangara cabeciazul","g":28},{"k":"Stilpnia vitriolina","common":"Tangara rastrojera","alt":"Scrub Tanager","sci":"Stilpnia vitriolina","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"Gris verdoso plateado, con la corona canela rojiza y un antifaz negro. Casi endémica de Colombia, muy común en zonas abiertas de las montañas.","diet":"Frutos, semillas e insectos.","habitat":"Rastrojos, cercas vivas, cafetales y jardines, entre unos 500 y 2.500 m.","sw":["#A8B8A8","#C2673A","#151515"],"photos":[{"img":"../barichara/fotos/stilpnia.jpg","mini":"../barichara/fotos/mini/stilpnia.jpg","ind":"Con un fruto en el pico","place":"Barichara, Santander"},{"img":"../cafetera/fotos/stilpnia3.jpg","mini":"../cafetera/fotos/mini/stilpnia3.jpg","ind":"Junto a un banano maduro","place":"Zona Cafetera"},{"img":"../cafetera/fotos/stilpnia2.jpg","mini":"../cafetera/fotos/mini/stilpnia2.jpg","ind":"En el comedero","place":"Zona Cafetera"},{"img":"../cafetera/fotos/stilpnia.jpg","mini":"../cafetera/fotos/mini/stilpnia.jpg","ind":"Entre hojas grandes","place":"Zona Cafetera"}],"where":[{"l":"barichara","nom":"Barichara","hab":"En parejas; muy confiada en los comederos.","donde":"Árboles frutales, rastrojos y cercas vivas.","id":"stilpnia-vitriolina"},{"l":"cafetera","nom":"Zona Cafetera","hab":"En parejas; muy confiada en los comederos.","donde":"Comederos, rastrojos y cercas vivas.","id":"stilpnia-vitriolina"}],"en":"Scrub Tanager","enAlt":"Tangara rastrojera","g":28},{"k":"Ramphocelus flammigerus","common":"Toche enjalmado","alt":"Asoma culirroja · Flame-rumped Tanager","sci":"Ramphocelus flammigerus","family":"Thraupidae","iucn":"LC","mig":false,"dom":false,"feral":false,"conf":"alta","desc":"El macho es negro aterciopelado con una rabadilla rojo anaranjado encendido, que solo se ve cuando abre las alas o se voltea. La hembra es muy distinta: cabeza y dorso pardo oscuro y pecho y rabadilla amarillo anaranjado. Ambos tienen el pico plateado. Es endémico de Colombia.","diet":"Frutos, sobre todo banano y moras, e insectos.","habitat":"Bordes de bosque, rastrojos, cafetales con sombrío y jardines, entre unos 500 y 1.800 m.","sw":["#121212","#F2502A","#F2B02A","#D8DCE0"],"photos":[{"img":"../cafetera/fotos/flammigerusM.jpg","mini":"../cafetera/fotos/mini/flammigerusM.jpg","ind":"Macho, con la rabadilla rojo fuego","place":"Zona Cafetera"},{"img":"../cafetera/fotos/flammigerusF.jpg","mini":"../cafetera/fotos/mini/flammigerusF.jpg","ind":"Hembra en el comedero","place":"Zona Cafetera"},{"img":"../cafetera/fotos/flammigerusF2.jpg","mini":"../cafetera/fotos/mini/flammigerusF2.jpg","ind":"Hembra, con el pecho anaranjado","place":"Zona Cafetera"},{"img":"../cafetera/fotos/flammigerusF3.jpg","mini":"../cafetera/fotos/mini/flammigerusF3.jpg","ind":"Hembra sobre una baranda","place":"Zona Cafetera"}],"where":[{"l":"cafetera","nom":"Zona Cafetera","hab":"Anda en grupos familiares ruidosos que llegan juntos al comedero. El macho abre las alas y muestra la rabadilla en sus despliegues.","donde":"Comederos de banano y bordes de cafetales.","id":"ramphocelus-flammigerus"}],"en":"Flame-rumped Tanager","enAlt":"Toche enjalmado · Asoma culirroja","g":28}];
